      --glass-2: #0d1d16;
      --glass-3: #12271d;
      --moss: #b5c77e;
      --moss-ink: #667744;
      --moss-deep: #728457;
      --gold: #e1be7f;
      --gold-ink: #9b722e;
      --rust: #c97155;
      --rust-ink: #9b4d38;
      --frost: #9db7be;
      --plague: #b18c9b;
      --drought: #c7a56e;
      --brass: #a68a59;
      --brass-light: #d2ba85;
      --serif: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, "Times New Roman", Georgia, serif;
      --mono: "SFMono-Regular", "SF Mono", "Cascadia Mono", "Roboto Mono", Menlo, Consolas, monospace;
      --sans: "Avenir Next", Avenir, "Helvetica Neue", Helvetica, Arial, sans-serif;
      --page-pad: clamp(16px, 2.5vw, 38px);
      --console-w: clamp(300px, 23vw, 344px);
      --ease: cubic-bezier(.22, .8, .25, 1);
    }

    *, *::before, *::after { box-sizing: border-box; }

    html { min-width: 320px; scroll-behavior: smooth; }

    body {
      margin: 0;
      min-width: 320px;
      min-height: 100vh;
      color: var(--ink);
      background:
        radial-gradient(1200px 780px at 72% -16%, rgba(255, 251, 238, 0.72), transparent 64%),
        radial-gradient(760px 600px at 0% 110%, rgba(89, 75, 46, 0.12), transparent 70%),
        repeating-linear-gradient(0deg, rgba(42, 45, 33, 0.018) 0, rgba(42, 45, 33, 0.018) 1px, transparent 1px, transparent 4px),
        var(--paper);
      font-family: var(--serif);
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
