      color: rgba(240, 232, 215, .38);
    }

    .chamber-read {
      position: absolute;
      top: clamp(16px, 2.3vw, 25px);
      right: clamp(16px, 2.3vw, 28px);
      display: flex;
      flex-direction: column;
      align-items: flex-end;
      gap: 5px;
      font-family: var(--mono);
      text-align: right;
      text-transform: uppercase;
      letter-spacing: .12em;
      color: rgba(240, 232, 215, .6);
      text-shadow: 0 1px 10px rgba(0,6,3,.9);
    }
    .chamber-read .cycle { font-size: 9px; }
    .chamber-read .cycle b { font-weight: 500; color: rgba(240,232,215,.9); }
    .chamber-read .night { font-size: 8px; color: rgba(240,232,215,.32); }

    .condition {
      position: absolute;
      top: clamp(76px, 10vw, 98px);
      right: clamp(16px, 2.3vw, 28px);
      display: flex;
      align-items: center;
      gap: 7px;
      padding: 5px 8px;
      border: 1px solid rgba(240, 232, 215, .16);
      background: rgba(5, 13, 9, .46);
      backdrop-filter: blur(3px);
      font: 8px/1.2 var(--mono);
      letter-spacing: .11em;
      text-transform: uppercase;
      color: rgba(240, 232, 215, .75);
      opacity: 0;
      transform: translateY(-4px);
      transition: opacity 300ms var(--ease), transform 300ms var(--ease);
    }
    .condition.is-live { opacity: 1; transform: translateY(0); }
    .condition .signal { width: 4px; height: 4px; border-radius: 50%; background: var(--condition-color, var(--drought)); box-shadow: 0 0 8px var(--condition-color, var(--drought)); }

    .species-key {
      position: absolute;
      left: clamp(14px, 2.3vw, 28px);
      bottom: clamp(14px, 2.2vw, 23px);
      display: flex;
      align-items: stretch;
      gap: 0;
      padding: 8px 0;
      border-top: 1px solid rgba(240, 232, 215, .14);
      border-bottom: 1px solid rgba(240, 232, 215, .14);
      background: linear-gradient(90deg, rgba(6, 14, 10, .62), rgba(6, 14, 10, 0));
      backdrop-filter: blur(4px);
      pointer-events: auto;
    }
    .key-item {
      display: grid;
      grid-template-columns: 17px auto;
      column-gap: 8px;
      align-items: center;
      padding: 0 clamp(10px, 1.25vw, 17px);
      min-width: 100px;
      border-right: 1px solid rgba(240, 232, 215, .12);
      color: rgba(240, 232, 215, .72);
    }
    .key-item:last-child { border-right: 0; }
    .key-glyph { width: 17px; height: 17px; color: var(--key-color); grid-row: span 2; }
    .key-glyph svg { display: block; width: 100%; height: 100%; overflow: visible; }
    .key-name { font-size: 12px; line-height: 1.1; font-style: italic; color: rgba(244, 236, 220, .92); white-space: nowrap; }
    .key-stat { font: 8px/1.4 var(--mono); letter-spacing: .08em; color: rgba(240, 232, 215, .46); white-space: nowrap; }
    .key-stat b { font-weight: 400; color: var(--key-color); }

    .graticule {
      position: absolute;
      right: clamp(14px, 2.3vw, 27px);
      bottom: clamp(14px, 2.2vw, 23px);
      display: flex;
      align-items: flex-end;
      gap: 13px;
      color: rgba(240, 232, 215, .38);
      font: 8px/1.2 var(--mono);
      letter-spacing: .09em;
      text-transform: uppercase;
      text-align: right;
    }
    .graticule .scale-bar { position: relative; width: 58px; height: 13px; border-bottom: 1px solid rgba(240,232,215,.35); }
    .graticule .scale-bar::before, .graticule .scale-bar::after { content: ""; position: absolute; bottom: 0; width: 1px; height: 5px; background: rgba(240,232,215,.35); }
    .graticule .scale-bar::before { left: 0; }
    .graticule .scale-bar::after { right: 0; }
    .graticule .scale-bar span { position: absolute; left: 50%; bottom: -9px; transform: translateX(-50%); font-size: 7px; color: rgba(240,232,215,.28); }
    .graticule .dir { writing-mode: vertical-rl; font-size: 7px; letter-spacing: .18em; color: rgba(240,232,215,.22); }

    .event-banner {
      position: absolute;
      top: clamp(92px, 13vw, 132px);
      left: 50%;
      width: min(390px, calc(100% - 48px));
      padding: 13px 16px 11px;
      background: rgba(237, 228, 209, .96);
      color: var(--ink);
      border: 1px solid rgba(32, 38, 30, .3);
      box-shadow: 0 12px 40px rgba(0, 6, 3, .38);
      opacity: 0;
      transform: translate(-50%, -9px);
      transition: opacity 360ms var(--ease), transform 360ms var(--ease);
      pointer-events: none;
    }
    .event-banner.is-visible { opacity: 1; transform: translate(-50%, 0); }
    .event-banner::before {
      content: "";
      position: absolute;
      inset: 4px;
      border: 1px dotted rgba(32, 38, 30, .2);
      pointer-events: none;
    }
    .event-banner .event-top {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 12px;
      position: relative;
      z-index: 1;
    }
    .event-banner .event-kind {
      font: 500 8px/1.3 var(--mono);
      letter-spacing: .15em;
      text-transform: uppercase;
      color: var(--event-ink, var(--rust-ink));
    }
    .event-banner .event-no { font: 8px/1.3 var(--mono); letter-spacing: .12em; color: var(--ink-faint); }
    .event-banner h2 {
      position: relative;
      z-index: 1;
      margin-top: 5px;
      font-size: 25px;
      line-height: 1;
      font-weight: 400;
      font-style: italic;
      letter-spacing: -.02em;
    }
    .event-banner p {
      position: relative;
      z-index: 1;
      margin-top: 5px;
      font-size: 12px;
      line-height: 1.35;
      color: var(--ink-soft);
      text-wrap: pretty;
    }

    .transport {
      display: grid;
      grid-template-columns: auto minmax(120px, 1fr) auto;
      align-items: center;
      gap: clamp(12px, 2vw, 24px);
      padding: 12px 8px 2px;
      color: var(--paper-high);
    }

    .transport-controls { display: flex; align-items: center; gap: 4px; }
    .icon-button {
      display: grid;
      place-items: center;
      width: 32px; height: 32px;
      padding: 0;
      border: 1px solid transparent;
      border-radius: 50%;
      background: transparent;
      color: rgba(240, 232, 215, .66);
      transition: background 160ms var(--ease), color 160ms var(--ease), border-color 160ms var(--ease);
    }
    .icon-button:hover { color: var(--paper-high); background: rgba(240, 232, 215, .08); }
    .icon-button.primary {
      width: 34px; height: 34px;
      border-color: rgba(207, 190, 152, .33);
      color: var(--paper-high);
    }
    .icon-button:focus-visible { outline-color: var(--brass-light); }
    .icon-button svg { width: 13px; height: 13px; display: block; }

    .progress-shell { min-width: 0; }
    .progress-meta {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      gap: 12px;
      margin-bottom: 8px;
      font: 8px/1.3 var(--mono);
      letter-spacing: .12em;
      text-transform: uppercase;
      color: rgba(240, 232, 215, .45);
    }
    .progress-meta .primary-meta { color: rgba(240, 232, 215, .9); letter-spacing: .1em; }
    .progress-meta .primary-meta b { font-weight: 400; color: var(--gold); }

    .timeline {
      position: relative;
      height: 4px;
      background: rgba(240, 232, 215, .12);
      border-radius: 0;
      overflow: visible;
    }
    .timeline-filled {
      position: absolute;
      left: 0; top: 0; bottom: 0;
      width: 0%;
      background: linear-gradient(90deg, var(--moss-deep), var(--moss));
      box-shadow: 0 0 9px rgba(181,199,126,.28);
    }
    .timeline::after {
      content: "";
      position: absolute;
      inset: 0;
      pointer-events: none;
      background: repeating-linear-gradient(90deg, rgba(240,232,215,.2) 0 1px, transparent 1px calc(100% / 12));
      opacity: .7;
    }
    .run-event {
      position: absolute;
      top: -9px;
      width: 1px; height: 15px;
      transform: translateX(-50%);
      background: var(--event-color, var(--drought));
      pointer-events: auto;
      border: 0;
      padding: 0;
    }
    .run-event::before {
      content: "";
      position: absolute;
      left: 50%; top: -4px;
      width: 5px; height: 5px;
      transform: translateX(-50%) rotate(45deg);
      background: var(--event-color, var(--drought));
    }
    .run-event:focus-visible { outline: 1px solid var(--paper-high); outline-offset: 3px; }

    .transport-tail {
      display: flex;
      align-items: center;
      gap: 13px;
      font: 8px/1.3 var(--mono);
      letter-spacing: .1em;
      text-transform: uppercase;
      color: rgba(240, 232, 215, .35);
      text-align: right;
      white-space: nowrap;
    }
    .transport-tail .next-event { color: rgba(240, 232, 215, .55); }
    .transport-tail .tempo-chip {
      padding: 4px 6px;
      border: 1px solid rgba(240, 232, 215, .16);
      color: var(--brass-light);
      letter-spacing: .06em;
    }

    .plate-footnote {
      display: flex;
      justify-content: space-between;
      gap: 20px;
      padding: 0 2px;
      font: 7.5px/1.5 var(--mono);
      letter-spacing: .09em;
      text-transform: uppercase;
      color: var(--ink-faint);
    }
    .plate-footnote em { font-family: var(--serif); font-size: 9px; letter-spacing: .01em; text-transform: none; }

    /* ---------- instrument console ---------- */

    .console {
      position: relative;
      min-height: 0;
      display: flex;
      flex-direction: column;
      background:
        linear-gradient(90deg, rgba(255,255,255,.2), transparent 16%),
        linear-gradient(180deg, rgba(245, 237, 222, .72), rgba(225, 213, 191, .5));
      border: 1px solid rgba(32, 38, 30, .33);
      box-shadow: 0 12px 34px -24px rgba(32, 38, 30, .6), inset 0 0 0 4px rgba(243, 235, 220, .22);
    }
    .console::before {
      content: "";
      position: absolute;
      left: -5px;
      top: 22px;
      width: 4px;
      height: 86px;
      background: var(--ink);
      box-shadow: 0 104px 0 var(--ink), 0 208px 0 var(--ink), 0 312px 0 var(--ink), 0 416px 0 var(--ink);
      opacity: .7;
    }

    .console-scroll { overflow: auto; min-height: 0; scrollbar-width: thin; scrollbar-color: rgba(32,38,30,.3) transparent; }
    .console-scroll::-webkit-scrollbar { width: 7px; }
    .console-scroll::-webkit-scrollbar-thumb { background: rgba(32,38,30,.26); }

    .console-head {
      position: relative;
      flex: 0 0 auto;
      padding: 17px 19px 13px;
      border-bottom: 1px solid var(--rule);
    }
    .console-head::after {
      content: "";
      position: absolute;
      left: 19px; right: 19px; bottom: 3px;
      height: 1px;
      background: var(--rule-faint);
    }
    .console-kicker {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      font: 500 8px/1.3 var(--mono);
      letter-spacing: .16em;
      text-transform: uppercase;
      color: var(--ink-faint);
    }
    .console-kicker .roman { color: var(--rust-ink); }
    .console-head h2 {
      margin-top: 7px;
      font-size: 24px;
      font-weight: 400;
      line-height: 1;
      letter-spacing: -.028em;
    }
    .console-head h2 em { color: var(--rust-ink); }
    .console-head p {
      max-width: 35ch;
      margin-top: 7px;
      font-size: 11.5px;
      font-style: italic;
      line-height: 1.35;
      color: var(--ink-soft);
    }

    .console-body { padding: 0 19px; }
    .control-group { padding: 12px 0 11px; border-bottom: 1px solid var(--rule); }
    .control-group:last-child { border-bottom: 0; }
    .group-head {
      display: flex;
      align-items: baseline;
      gap: 8px;
      margin-bottom: 9px;
    }
    .group-head .num {
      width: 14px;
      color: var(--rust-ink);
      font: 8px/1.3 var(--mono);
      letter-spacing: -.02em;
    }
    .group-head h3 {
      font: 500 8.5px/1.3 var(--mono);
      letter-spacing: .15em;
      text-transform: uppercase;
      color: var(--ink);
    }
    .group-head .latin {
      margin-left: auto;
      font-size: 9px;
      font-style: italic;
      color: var(--ink-faint);
      letter-spacing: .02em;
    }

    .control {
      position: relative;
      padding: 3px 0 4px;
    }
    .control + .control { margin-top: 7px; }
    .control:focus-within .control-label { color: var(--ink); }

    .control-top {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 10px;
      min-height: 17px;
    }
    .control-label {
      font-size: 12.5px;
      line-height: 1.2;
      letter-spacing: .005em;
      color: var(--ink-soft);
      transition: color 160ms var(--ease);
    }
    .control-label .marker {
      display: inline-block;
      margin-left: 4px;
      color: var(--ink-faint);
      font: 7px/1 var(--mono);
      letter-spacing: .06em;
      vertical-align: 2px;
    }
    .readout {
      display: inline-flex;
      align-items: baseline;
      gap: 4px;
      color: var(--ink);
      font: 10px/1.2 var(--mono);
      letter-spacing: .015em;
      white-space: nowrap;
    }
    .readout .unit {
      color: var(--ink-faint);
      font: 7.5px/1.2 var(--mono);
      letter-spacing: .09em;
      text-transform: uppercase;
    }

    .field-row {
      display: flex;
      align-items: center;
      gap: 10px;
      min-height: 27px;
    }

    .range-wrap {
      position: relative;
      flex: 1;
      min-width: 0;
      padding: 8px 0 6px;
    }
    .range-wrap::after {
      content: "";
      position: absolute;
      left: 0; right: 0; bottom: 1px;
      height: 3px;
      pointer-events: none;
      background: repeating-linear-gradient(90deg, var(--rule) 0 1px, transparent 1px calc(100% / 12));
      opacity: .7;
    }
    input[type="range"] {
      -webkit-appearance: none;
      appearance: none;
      display: block;
      width: 100%;
      height: 16px;
      margin: 0;
      padding: 0;
      background: transparent;
      cursor: ew-resize;
    }
    input[type="range"]::-webkit-slider-runnable-track {
      height: 2px;
      background: linear-gradient(90deg, var(--ink) 0 var(--fill, 40%), rgba(32,38,30,.18) var(--fill, 40%) 100%);
    }
    input[type="range"]::-moz-range-track { height: 2px; background: rgba(32,38,30,.18); }
    input[type="range"]::-moz-range-progress { height: 2px; background: var(--ink); }
    input[type="range"]::-webkit-slider-thumb {
      -webkit-appearance: none;
      width: 10px; height: 10px;
      margin-top: -4px;
      border: 1px solid var(--ink);
      border-radius: 50%;
      background: var(--paper-high);
      box-shadow: 0 0 0 2px var(--paper), 0 1px 3px rgba(32,38,30,.25);
      transition: transform 140ms var(--ease), background 140ms var(--ease);
    }
    input[type="range"]::-moz-range-thumb {
      width: 10px; height: 10px;
      border: 1px solid var(--ink);
      border-radius: 50%;
      background: var(--paper-high);
      box-shadow: 0 0 0 2px var(--paper);
    }
    input[type="range"]:hover::-webkit-slider-thumb { transform: scale(1.2); background: var(--brass-light); }
    input[type="range"]:active::-webkit-slider-thumb { transform: scale(1.05); background: var(--brass); }
    input[type="range"]:focus-visible { outline: none; }
    input[type="range"]:focus-visible::-webkit-slider-thumb { outline: 2px solid var(--rust-ink); outline-offset: 3px; }
    input[type="range"]:focus-visible::-moz-range-thumb { outline: 2px solid var(--rust-ink); outline-offset: 3px; }

    .spark {
      display: block;
      flex: 0 0 auto;
      width: 58px;
      height: 20px;
      opacity: .8;
    }
    .spark.small { width: 48px; height: 17px; }

    .range-legend {
      display: flex;
      justify-content: space-between;
      gap: 8px;
      margin-top: 1px;
      font: 7px/1.2 var(--mono);
      letter-spacing: .06em;
      color: var(--ink-faint);
    }

    .stepper {
      display: inline-flex;
      align-items: stretch;
      height: 26px;
      border: 1px solid var(--rule);
      background: rgba(248, 242, 229, .36);
    }
    .step-button {
      display: grid;
      place-items: center;
      width: 24px;
      padding: 0;
      border: 0;
      background: transparent;
      color: var(--ink-soft);
      font: 14px/1 var(--mono);
      transition: background 130ms var(--ease), color 130ms var(--ease);
    }
    .step-button:hover { color: var(--ink); background: rgba(32,38,30,.07); }
    .step-button:active { background: rgba(32,38,30,.12); }
    .step-button:focus-visible { outline-offset: -2px; }
    .stepper-value {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-width: 44px;
      padding: 0 4px;
      border-left: 1px solid var(--rule-faint);
      border-right: 1px solid var(--rule-faint);
      color: var(--ink);
      font: 10px/1 var(--mono);
    }
    .seed-field .stepper-value { min-width: 68px; border: 0; padding: 0; }
    .seed-field input {
      width: 74px;
      border: 0;
      border-left: 1px solid var(--rule-faint);
      border-right: 1px solid var(--rule-faint);
      background: transparent;
      color: var(--ink);
      font: 10px/1 var(--mono);
      letter-spacing: .07em;
      text-align: center;
      padding: 8px 2px;
      border-radius: 0;
    }
    .seed-field input:focus-visible { outline: 2px solid var(--rust-ink); outline-offset: -2px; }

    .button-mini {
      display: grid;
      place-items: center;
      width: 26px; height: 26px;
      padding: 0;
      border: 1px solid var(--rule);
      background: rgba(248,242,229,.32);
      color: var(--ink-soft);
      transition: color 130ms var(--ease), background 130ms var(--ease), border-color 130ms var(--ease);
    }
    .button-mini:hover { color: var(--ink); border-color: var(--rule); background: rgba(32,38,30,.06); }
    .button-mini svg { width: 11px; height: 11px; }

    .unit-line {
      margin-left: auto;
      font: 7.5px/1.2 var(--mono);
      letter-spacing: .1em;
      text-transform: uppercase;
      color: var(--ink-faint);
    }

    /* custom dial */
    .dial-control {
      display: grid;
      grid-template-columns: 78px minmax(0, 1fr);
      align-items: center;
      gap: 13px;
      padding-top: 1px;
    }
    .dial-unit {
      display: flex;
      flex-direction: column;
      gap: 5px;
      min-width: 0;
    }
    .dial-hint {
      font-size: 10.5px;
      line-height: 1.3;
      font-style: italic;
      color: var(--ink-soft);
      text-wrap: pretty;
    }
    .dial-scale {
      display: flex;
      justify-content: space-between;
      gap: 5px;
      font: 7px/1.2 var(--mono);
      letter-spacing: .08em;
      color: var(--ink-faint);
    }
    .dial {
      position: relative;
      width: 78px;
      height: 78px;
      border-radius: 50%;
      cursor: ns-resize;
      touch-action: none;
      color: var(--ink);
      background: radial-gradient(circle at 41% 32%, rgba(255,255,255,.44), transparent 45%), rgba(219, 205, 180, .35);
      border: 1px solid rgba(32,38,30,.25);
      box-shadow: inset 0 0 0 4px rgba(243,235,220,.45), 0 2px 7px rgba(32,38,30,.12);
    }
    .dial:focus-visible { outline: 2px solid var(--rust-ink); outline-offset: 4px; }
    .dial svg { position: absolute; inset: 5px; width: calc(100% - 10px); height: calc(100% - 10px); overflow: visible; pointer-events: none; }
    .dial .dial-readout {
      position: absolute;
      inset: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 2px;
      pointer-events: none;
    }
    .dial .dial-readout b { font: 13px/1 var(--mono); font-weight: 400; letter-spacing: -.04em; }
    .dial .dial-readout span { font: 6.5px/1 var(--mono); letter-spacing: .1em; text-transform: uppercase; color: var(--ink-faint); }

    /* disturbance switches */
    .event-controls { display: flex; flex-direction: column; gap: 1px; }
    .event-control {
      display: grid;
      grid-template-columns: 24px minmax(70px, 1fr) auto 48px;
      align-items: center;
      gap: 8px;
      min-height: 32px;
      padding: 2px 0;
      border-top: 1px dotted var(--rule-faint);
    }
    .event-control:first-child { border-top: 1px solid transparent; }
    .event-switch {
      position: relative;
      width: 22px; height: 12px;
      padding: 0;
      border: 1px solid rgba(32,38,30,.35);
      border-radius: 20px;
      background: rgba(32,38,30,.06);
      transition: background 160ms var(--ease), border-color 160ms var(--ease);
    }
    .event-switch::after {
      content: "";
      position: absolute;
      top: 1px; left: 1px;
      width: 8px; height: 8px;
      border-radius: 50%;
      background: var(--paper-high);
      box-shadow: 0 1px 2px rgba(32,38,30,.35);
      transition: transform 180ms var(--ease), background 160ms var(--ease);
    }
    .event-switch[aria-checked="true"] { background: var(--event-ink, var(--ink)); border-color: var(--event-ink, var(--ink)); }
    .event-switch[aria-checked="true"]::after { transform: translateX(10px); background: var(--paper-high); }
    .event-switch:focus-visible { outline: 2px solid var(--rust-ink); outline-offset: 2px; }
    .event-switch[data-kind="drought"] { --event-ink: #8e6b36; }
    .event-switch[data-kind="plague"] { --event-ink: #865f70; }
    .event-switch[data-kind="frost"] { --event-ink: #5f7b84; }

    .event-name {
      display: flex;
      align-items: baseline;
      gap: 7px;
      min-width: 0;
    }
    .event-name .name {
      font-size: 11.5px;
      line-height: 1.2;
      color: var(--ink);
    }
    .event-name .note {
      overflow: hidden;
      color: var(--ink-faint);
