    /* ---------- the closing report ---------- */

    .report {
      position: fixed;
      inset: 0;
      z-index: 80;
      display: flex;
      flex-direction: column;
      overflow-y: auto;
      background:
        radial-gradient(1100px 680px at 70% -10%, rgba(255, 250, 237, .8), transparent 60%),
