    .report-brand p { font: 500 8px/1.4 var(--mono); letter-spacing: .16em; text-transform: uppercase; color: var(--ink-soft); }
    .report-actions { display: flex; align-items: center; gap: 8px; }
    .paper-button {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      min-height: 31px;
      padding: 0 12px;
      border: 1px solid var(--rule);
      background: transparent;
      color: var(--ink-soft);
      font: 8px/1.2 var(--mono);
