    .paper-button:hover { color: var(--ink); border-color: rgba(32,38,30,.4); background: rgba(255,255,255,.17); }
    .paper-button.primary { color: var(--paper-high); background: var(--ink); border-color: var(--ink); }
    .paper-button.primary:hover { background: #30382c; }
    .paper-button svg { width: 10px; height: 10px; }

    .report-intro {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 38px;
      align-items: end;
      padding: 26px 0 21px;
    }
    .report-title {
      max-width: 850px;
      font-size: clamp(38px, 5.2vw, 76px);
      font-weight: 400;
      line-height: .94;
      letter-spacing: -.045em;
      text-wrap: balance;
    }
    .report-title em { color: var(--rust-ink); font-style: italic; }
    .report-deck {
      max-width: 70ch;
      margin-top: 13px;
      color: var(--ink-soft);
      font-size: 15px;
      line-height: 1.48;
      font-style: italic;
      text-wrap: pretty;
    }
    .closing-stamp {
      position: relative;
      flex: 0 0 auto;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      width: 128px; height: 128px;
      border: 1px solid rgba(155, 77, 56, .5);
