    }
    .closing-stamp::before { content: ""; position: absolute; inset: 5px; border: 1px dotted rgba(155, 77, 56, .44); border-radius: 50%; }
    .closing-stamp strong { display: block; font-family: var(--serif); font-size: 26px; font-weight: 400; letter-spacing: -.03em; line-height: 1; }
    .closing-stamp span { display: block; margin-top: 4px; }

    .report-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 0;
      margin: 0 0 23px;
      border-top: 1px solid var(--ink);
      border-bottom: 1px solid var(--rule);
    }
    .report-meta div {
      flex: 1 1 125px;
      padding: 8px 14px 9px;
      border-right: 1px dotted var(--rule);
    }
    .report-meta div:last-child { border-right: 0; }
    .report-meta dt { font: 7px/1.3 var(--mono); letter-spacing: .14em; text-transform: uppercase; color: var(--ink-faint); }
    .report-meta dd { margin-top: 3px; font: 10px/1.3 var(--mono); color: var(--ink); }
    .report-meta dd em { font-family: var(--serif); font-size: 12px; }

    .report-grid {
      display: grid;
      grid-template-columns: minmax(0, 1fr) 310px;
      gap: 20px;
      align-items: stretch;
    }
    .figure {
      position: relative;
      border-top: 2px solid var(--ink);
      padding-top: 9px;
    }
    .figure-head {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 14px;
      min-height: 24px;
    }
    .figure-kicker { font: 500 8px/1.3 var(--mono); letter-spacing: .14em; text-transform: uppercase; color: var(--ink-faint); }
    .figure-title { margin-top: 3px; font-size: 22px; line-height: 1.1; font-weight: 400; letter-spacing: -.02em; }
    .figure-title em { color: var(--rust-ink); }
    .chart-legend { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 10px; font: 7px/1.3 var(--mono); letter-spacing: .06em; text-transform: uppercase; color: var(--ink-soft); }
    .chart-legend span { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
    .swatch { display: inline-block; width: 12px; height: 2px; background: var(--swatch); }
    .swatch.dashed { height: 1px; background: repeating-linear-gradient(90deg, var(--swatch) 0 3px, transparent 3px 5px); }
    .swatch.area { height: 7px; opacity: .3; background: var(--swatch); }
    .swatch.event { width: 2px; height: 9px; }

    .population-figure { min-width: 0; }
    .population-chart-wrap { position: relative; margin-top: 8px; }
    #populationChart { display: block; width: 100%; height: 338px; }
    .chart-tip {
      position: absolute;
      z-index: 4;
      min-width: 155px;
      padding: 8px 10px;
      background: rgba(30, 37, 28, .96);
      color: rgba(242, 234, 218, .9);
      border: 1px solid rgba(209,186,138,.26);
      font: 8px/1.6 var(--mono);
      letter-spacing: .035em;
      pointer-events: none;
      opacity: 0;
      transform: translateY(3px);
      transition: opacity 100ms ease;
    }
    .chart-tip.is-visible { opacity: 1; transform: translateY(0); }
    .chart-tip strong { display: block; margin-bottom: 3px; color: var(--brass-light); font-weight: 400; letter-spacing: .08em; text-transform: uppercase; }
    .chart-tip .tip-row { display: flex; justify-content: space-between; gap: 16px; }
    .chart-tip .tip-event { margin-top: 5px; padding-top: 4px; border-top: 1px solid rgba(240,232,215,.17); color: var(--gold); }
    .chart-note { display: flex; justify-content: space-between; gap: 18px; margin-top: 2px; font: 7px/1.4 var(--mono); letter-spacing: .06em; text-transform: uppercase; color: var(--ink-faint); }

    .ledger {
      display: flex;
      flex-direction: column;
      min-width: 0;
      border-top: 2px solid var(--ink);
      padding-top: 9px;
    }
    .ledger-title { margin-top: 3px; font-size: 22px; line-height: 1.1; font-weight: 400; letter-spacing: -.02em; }
    .ledger-title em { color: var(--rust-ink); }
    .ledger-stats {
      display: grid;
      grid-template-columns: 1fr 1fr;
      border-top: 1px solid var(--rule);
      margin-top: 13px;
    }
    .ledger-stat { padding: 9px 0 10px; border-bottom: 1px dotted var(--rule); }
    .ledger-stat:nth-child(odd) { border-right: 1px solid var(--rule); padding-right: 13px; }
    .ledger-stat:nth-child(even) { padding-left: 13px; }
    .ledger-stat dt { font: 7px/1.3 var(--mono); letter-spacing: .1em; text-transform: uppercase; color: var(--ink-faint); }
    .ledger-stat dd { margin-top: 3px; font: 14px/1.1 var(--mono); color: var(--ink); }
    .ledger-stat dd small { font-size: 8px; color: var(--ink-faint); }
    .event-ledger { margin-top: 12px; }
    .event-ledger h3 { font: 500 8px/1.3 var(--mono); letter-spacing: .13em; text-transform: uppercase; color: var(--ink-faint); }
    .event-ledger-list { max-height: 177px; overflow: auto; margin-top: 4px; padding-right: 5px; scrollbar-width: thin; scrollbar-color: rgba(32,38,30,.25) transparent; }
    .event-entry {
      display: grid;
      grid-template-columns: 35px 7px 1fr;
      gap: 7px;
      align-items: start;
      padding: 5px 0;
      border-bottom: 1px dotted var(--rule-faint);
      font: 8px/1.4 var(--mono);
      color: var(--ink-soft);
    }
    .event-entry .eg { color: var(--ink-faint); }
    .event-entry .dot { width: 4px; height: 4px; margin-top: 4px; transform: rotate(45deg); background: var(--event-color, var(--drought)); }
    .event-entry b { display: block; font-family: var(--serif); font-size: 11px; font-weight: 400; color: var(--ink); }
    .event-entry span { display: block; }
    .event-empty { padding: 8px 0; font-size: 11px; font-style: italic; color: var(--ink-faint); }
    .ledger-foot { margin-top: auto; padding-top: 12px; font: 7px/1.55 var(--mono); letter-spacing: .06em; color: var(--ink-faint); }

    .traits-figure { grid-column: 1 / -1; margin-top: 4px; }
