    .report-footer {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 20px;
      margin-top: 18px;
      padding-top: 12px;
      border-top: 1px solid var(--ink);
      font: 7.5px/1.5 var(--mono);
      letter-spacing: .08em;
      text-transform: uppercase;
      color: var(--ink-faint);
    }
    .report-footer .actions { display: flex; gap: 8px; }
    .report-footer .closing-line { max-width: 56ch; }
    .report-footer .closing-line em { font-family: var(--serif); font-size: 10px; letter-spacing: 0; text-transform: none; color: var(--ink-soft); }

    @media (max-width: 1050px) {
