 const numericString = String(numeric).padStart(6,'0');
 const h = xmur3('nocturne:' + numericString + ':' + salt)();
 return h>>>0;
}
function deriveSeed(n) { let x = (n * 1664525 + 1013904223) ^ ...; return Math.abs(x)%1000000; }
