const fs=require('fs'),vm=require('vm');
const html=fs.readFileSync('index.html','utf8');
const m=html.match(/<script>\s*\/\* =+\n\s*I\. THE ENGINE[\s\S]*?<\/script>/);
const code=m[0].replace(/^<script>/,'').replace(/<\/script>$/,'');
const sandbox={window:{},console,Math};vm.createContext(sandbox);vm.runInContext(code,sandbox);
const {VivariumEngine}=sandbox.window.Nocturne;
let e=new VivariumEngine({seed:1897});
for(let g=1;g<=8;g++){
 while(e.generation<g) e.step();
 const h=e.history.at(-1);
 console.log(g, 'prey',h.prey,'pred',h.predator,'births',h.births,'deaths',h.deaths,'moss',Math.round(h.plantCover*100),'preyE',e.prey.length?Math.round(e.prey.reduce((s,a)=>s+a.energy,0)/e.prey.length):'-','predE',e.predators.length?Math.round(e.predators.reduce((s,a)=>s+a.energy,0)/e.predators.length):'-');
}
// track counts at finer intervals gen1
e=new VivariumEngine({seed:1897});
for(let t=0;t<=180;t+=30){ console.log('tick',e.tick,'p',e.prey.length,'d',e.predators.length,'avg p energy',e.prey.length?Math.round(e.prey.reduce((s,a)=>s+a.energy,0)/e.prey.length):'-','d',e.predators.length?Math.round(e.predators.reduce((s,a)=>s+a.energy,0)/e.predators.length):'-'); if(t<180){for(let i=0;i<30;i++)e.step();}}
