from pathlib import Path
p=Path('index.html'); s=p.read_text()
marker='''  <script>
    /* ============================================================
       II. THE PICTURE, INSTRUMENTS, AND CLOSING REPORT
       ============================================================ */
  </script>
</body>'''
renderer=r'''  <script>
    /* ============================================================
       II. THE PICTURE
       A renderer that reads the engine and never writes to it.
       ============================================================ */
    (() => {
      'use strict';
      const N = window.Nocturne;
      const { WORLD, CELLS } = N;
      const TAU = Math.PI * 2;

      const PALETTE = {
        prey: '#e1be7f',
        preyRgb: '225,190,127',
        predator: '#c97155',
        predatorRgb: '201,113,85',
        plant: '#b5c77e',
        plantRgb: '181,199,126',
        frost: '#9db7be',
        plague: '#b18c9b',
        drought: '#c7a56e',
        paper: '#e8deca',
        ink: '#20261e'
      };

      const rgba = (rgb, alpha) => `rgba(${rgb},${alpha})`;

      function makeGlowSprite(rgb) {
        const size = 64;
        const c = document.createElement('canvas');
        c.width = size;
        c.height = size;
        const ctx = c.getContext('2d');
        const grad = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
        grad.addColorStop(0, rgba(rgb, 0.55));
        grad.addColorStop(0.16, rgba(rgb, 0.24));
        grad.addColorStop(0.5, rgba(rgb, 0.08));
        grad.addColorStop(1, rgba(rgb, 0));
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, size, size);
        return c;
      }

      function makeSoftField(color, transparent = 0) {
        const size = 128;
        const c = document.createElement('canvas');
        c.width = size;
        c.height = size;
        const ctx = c.getContext('2d');
        const grad = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, size, size);
        return c;
      }

      class VivariumView {
        constructor(canvas, engine) {
          this.canvas = canvas;
          this.ctx = canvas.getContext('2d', { alpha: false });
          this.engine = engine;
          this.effects = [];
          this.preyGlow = makeGlowSprite(PALETTE.preyRgb);
          this.predatorGlow = makeGlowSprite(PALETTE.predatorRgb);
          this.mossField = makeSoftField('rgba(93,117,72,.11)');
          this.w = 0;
          this.h = 0;
          this.dpr = 1;
          this.reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
          this.reseed(engine);
          this.resize();
        }

        reseed(engine) {
          this.engine = engine;
          const viewRng = N.makeViewRandom(engine.seed);
          this.viewRng = viewRng;
          this.effects = [];
          this.jitter = new Float32Array(CELLS * 2);
          for (let i = 0; i < CELLS; i++) {
            this.jitter[i * 2] = viewRng.range(-0.45, 0.45);
            this.jitter[i * 2 + 1] = viewRng.range(-0.45, 0.45);
          }
          this.motes = Array.from({ length: 84 }, () => ({
            x: viewRng.next(),
            y: viewRng.next(),
            r: viewRng.range(0.35, 1.6),
            speed: viewRng.range(0.0015, 0.009),
            phase: viewRng.range(0, TAU),
            alpha: viewRng.range(0.12, 0.5)
          }));
          this.staticStars = new Set();
          // A sparse constellation of tiny botanical flecks, fixed per seed.
          for (let i = 0; i < CELLS; i++) {
            if (viewRng.chance(0.0021)) this.staticStars.add(i);
          }
        }

        resize() {
          const rect = this.canvas.getBoundingClientRect();
          const width = Math.max(2, rect.width);
          const height = Math.max(2, rect.height);
          const dpr = Math.min(window.devicePixelRatio || 1, 2);
          if (this.w === width && this.h === height && this.dpr === dpr) return false;
          this.w = width;
          this.h = height;
          this.dpr = dpr;
          this.canvas.width = Math.round(width * dpr);
          this.canvas.height = Math.round(height * dpr);
          this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
          this.sx = width / WORLD.width;
          this.sy = height / WORLD.height;
          this.glowScale = Math.min(this.sx, this.sy);
          this.buildBackground();
          return true;
        }

        buildBackground() {
          const { ctx, w, h } = this;
          if (!ctx) return;
          const bg = ctx.createLinearGradient(0, 0, w * 0.25, h);
          bg.addColorStop(0, '#0b1b14');
          bg.addColorStop(0.48, '#081510');
          bg.addColorStop(1, '#050e0a');
          this.bgGradient = bg;
          const light = ctx.createRadialGradient(w * 0.56, h * 0.33, 0, w * 0.56, h * 0.33, Math.max(w, h) * 0.62);
          light.addColorStop(0, 'rgba(115,146,97,.11)');
          light.addColorStop(0.5, 'rgba(60,92,62,.035)');
          light.addColorStop(1, 'rgba(0,0,0,0)');
          this.lightGradient = light;
          const corner = ctx.createLinearGradient(0, 0, 0, h);
          corner.addColorStop(0, 'rgba(4,11,7,.28)');
          corner.addColorStop(0.15, 'rgba(4,11,7,0)');
          corner.addColorStop(0.8, 'rgba(4,11,7,0)');
          corner.addColorStop(1, 'rgba(4,11,7,.34)');
          this.cornerGradient = corner;
        }

        addEffect(kind, x, y, meta = {}) {
          if (!this.viewRng) return;
          const probabilities = {
            graze: 0.22,
            birth: 0.44,
            starve: 0.7,
            pass: 0.45,
            kill: 1,
            blight: 0.42,
            feed: 0.5,
            weather: 1
          };
          if (!this.viewRng.chance(probabilities[kind] ?? 0.5)) return;
          const ttl = kind === 'weather' ? 2300 : kind === 'kill' ? 760 : 620;
          this.effects.push({
            kind,
            x,
            y,
            meta,
            born: performance.now(),
            ttl,
            seed: this.viewRng.next(),
            dx: this.viewRng.range(-1, 1),
            dy: this.viewRng.range(-1, 1)
          });
          if (this.effects.length > 90) this.effects.splice(0, this.effects.length - 90);
        }

        clearEffects() {
          this.effects.length = 0;
        }

        draw(now) {
          const { ctx, w, h } = this;
          if (!ctx || !w || !h) return;
          ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
          ctx.globalCompositeOperation = 'source-over';
          ctx.globalAlpha = 1;
          ctx.fillStyle = this.bgGradient;
          ctx.fillRect(0, 0, w, h);
          ctx.fillStyle = this.lightGradient;
          ctx.fillRect(0, 0, w, h);
          this.drawGraticule();
          this.drawMotes(now);
          this.drawMossField();
          this.drawPlants(now);
          this.drawAgents(now);
          this.drawEffects(now);
          ctx.fillStyle = this.cornerGradient;
          ctx.fillRect(0, 0, w, h);
          this.drawEdgeMarks();
        }

        drawGraticule() {
          const { ctx, w, h, sx, sy } = this;
          ctx.save();
          ctx.lineWidth = 0.5;
          ctx.strokeStyle = 'rgba(222,211,184,.055)';
          for (let x = sx * 12; x < w; x += sx * 12) {
            ctx.beginPath();
            ctx.moveTo(x, 0);
            ctx.lineTo(x, h);
            ctx.stroke();
          }
          for (let y = sy * 12; y < h; y += sy * 12) {
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(w, y);
            ctx.stroke();
          }

          ctx.strokeStyle = 'rgba(207,198,172,.065)';
          ctx.lineWidth = 0.7;
          ctx.beginPath();
          ctx.arc(w * 0.52, h * 0.47, Math.min(w, h) * 0.385, 0, TAU);
          ctx.stroke();
          ctx.setLineDash([1, 8]);
          ctx.beginPath();
          ctx.arc(w * 0.52, h * 0.47, Math.min(w, h) * 0.265, 0, TAU);
          ctx.stroke();
          ctx.setLineDash([]);

          // A quiet crosshair under the life, like marks on the reverse of the glass.
          ctx.strokeStyle = 'rgba(207,198,172,.045)';
          ctx.beginPath();
          ctx.moveTo(w * 0.52, h * 0.47 - Math.min(w, h) * 0.385);
          ctx.lineTo(w * 0.52, h * 0.47 + Math.min(w, h) * 0.385);
          ctx.moveTo(w * 0.52 - Math.min(w, h) * 0.47, h * 0.47);
          ctx.lineTo(w * 0.52 + Math.min(w, h) * 0.47, h * 0.47);
          ctx.stroke();

          // Radial measurement ticks.
          ctx.save();
          ctx.translate(w * 0.52, h * 0.47);
          const radius = Math.min(w, h) * 0.385;
          for (let i = 0; i < 48; i++) {
            const angle = i * TAU / 48;
            const major = i % 4 === 0;
            const inner = radius - (major ? 6 : 3);
            ctx.strokeStyle = major ? 'rgba(218,205,174,.12)' : 'rgba(218,205,174,.06)';
            ctx.beginPath();
            ctx.moveTo(Math.cos(angle) * inner, Math.sin(angle) * inner);
            ctx.lineTo(Math.cos(angle) * (radius + 3), Math.sin(angle) * (radius + 3));
            ctx.stroke();
          }
          ctx.restore();

          // Tiny coordinate notations at the margins.
          ctx.fillStyle = 'rgba(221,211,184,.26)';
          ctx.font = '7px "SFMono-Regular", Menlo, Consolas, monospace';
          ctx.textAlign = 'left';
          ctx.fillText('00', 18, h - 17);
          ctx.textAlign = 'right';
          ctx.fillText('168 × 104', w - 18, h - 17);
          ctx.restore();
        }

        drawMotes(now) {
          const { ctx, w, h } = this;
          const t = this.reducedMotion ? 0 : now * 0.001;
          ctx.save();
          ctx.globalCompositeOperation = 'lighter';
          for (const p of this.motes) {
            const y = ((p.y + t * p.speed) % 1 + 1) % 1;
            const x = p.x + Math.sin(t * 0.35 + p.phase) * 0.006;
            const alpha = p.alpha * (0.65 + Math.sin(t * 0.55 + p.phase) * 0.35);
            ctx.fillStyle = `rgba(214,204,176,${Math.max(0, alpha * 0.5)})`;
            ctx.beginPath();
            ctx.arc(x * w, (1 - y) * h, p.r, 0, TAU);
            ctx.fill();
          }
          ctx.restore();
        }

        drawMossField() {
          const { ctx, w, h } = this;
          const cover = this.engine ? this.engine.summaryStats().cover : 0.3;
          ctx.save();
          ctx.globalAlpha = Math.min(1, 0.35 + cover * 0.9);
          ctx.drawImage(this.mossField, w * 0.16, h * 0.14, w * 0.74, h * 0.76);
          ctx.restore();
        }

        drawPlants(now) {
          const { ctx, w, h, sx, sy } = this;
          const engine = this.engine;
          if (!engine) return;
          const plants = engine.plants;
          const base = Math.min(sx, sy);
          const paths = [new Path2D(), new Path2D(), new Path2D()];
          for (let i = 0; i < CELLS; i++) {
            const b = plants[i];
            if (b < 0.022) continue;
            const gx = i % WORLD.width;
            const gy = (i / WORLD.width) | 0;
            const px = (gx + 0.5 + this.jitter[i * 2]) * sx;
            const py = (gy + 0.5 + this.jitter[i * 2 + 1]) * sy;
            const size = Math.max(0.65, base * (0.11 + b * 0.24));
            const bucket = b > 0.63 ? 2 : b > 0.27 ? 1 : 0;
            paths[bucket].rect(px - size / 2, py - size / 2, size, size);
          }
          ctx.save();
          ctx.globalCompositeOperation = 'lighter';
          ctx.fillStyle = 'rgba(112,135,83,.23)';
          ctx.fill(paths[0]);
          ctx.fillStyle = 'rgba(159,181,110,.35)';
          ctx.fill(paths[1]);
          ctx.fillStyle = 'rgba(203,217,150,.51)';
          ctx.fill(paths[2]);

          // The most established cells are allowed a tiny botanical star.
          ctx.strokeStyle = 'rgba(216,225,168,.31)';
          ctx.lineWidth = 0.55;
          let drawn = 0;
          for (let i = 0; i < CELLS && drawn < 72; i++) {
            if (plants[i] < 0.72) continue;
            if (!this.staticStars.has(i) && (i * 37 + 11) % 113 !== 0) continue;
            const gx = i % WORLD.width;
            const gy = (i / WORLD.width) | 0;
            const px = (gx + 0.5 + this.jitter[i * 2]) * sx;
            const py = (gy + 0.5 + this.jitter[i * 2 + 1]) * sy;
            const r = base * 0.23 + 0.6;
            const sway = Math.sin(now * 0.00022 + i) * 0.18;
            ctx.beginPath();
            ctx.moveTo(px, py - r);
            ctx.lineTo(px + Math.cos(sway) * r, py + Math.sin(sway) * r * 0.8);
            ctx.moveTo(px - r * 0.8, py);
            ctx.lineTo(px + r * 0.8, py);
            ctx.stroke();
            drawn += 1;
          }
          ctx.restore();
        }

        drawAgents(now) {
          const { ctx, sx, sy } = this;
          const engine = this.engine;
          if (!engine) return;
          const base = Math.min(sx, sy);
          const t = this.reducedMotion ? 0 : now * 0.001;

          ctx.save();
          ctx.globalCompositeOperation = 'lighter';
          for (const a of engine.prey) {
            if (!a.alive) continue;
            const px = (a.x + 0.5) * sx;
            const py = (a.y + 0.5) * sy;
            const readiness = N.clamp(a.energy / Math.max(1, a.genes.repro), 0.15, 1.35);
            const glow = base * (2.6 + readiness * 1.1);
            ctx.globalAlpha = 0.33 + readiness * 0.29;
            ctx.drawImage(this.preyGlow, px - glow / 2, py - glow / 2, glow, glow);
          }
          for (const a of engine.predators) {
            if (!a.alive) continue;
            const px = (a.x + 0.5) * sx;
            const py = (a.y + 0.5) * sy;
            const glow = base * (4.5 + Math.min(2, a.energy / Math.max(1, a.genes.repro)) * 1.7);
            ctx.globalAlpha = 0.25 + Math.min(0.25, a.digest <= 0 ? 0.15 : 0.03);
            ctx.drawImage(this.predatorGlow, px - glow / 2, py - glow / 2, glow, glow);
