            ctx.drawImage(this.preyGlow, px - glow / 2, py - glow / 2, glow, glow);
          }
          for (const a of engine.predators) {
            if (!a.alive) continue;
            const px = (a.x + 0.5) * sx;
            const py = (a.y + 0.5) * sy;
            const glow = base * (4.5 + Math.min(2, a.energy / Math.max(1, a.genes.repro)) * 1.7);
            ctx.globalAlpha = 0.25 + Math.min(0.25, a.digest <= 0 ? 0.15 : 0.03);
            ctx.drawImage(this.predatorGlow, px - glow / 2, py - glow / 2, glow, glow);
          }
          ctx.globalAlpha = 1;
          ctx.globalCompositeOperation = 'source-over';

          const preyReady = base * 0.96;
          for (const a of engine.prey) {
            if (!a.alive) continue;
            const px = (a.x + 0.5) * sx;
            const py = (a.y + 0.5) * sy;
            const readiness = N.clamp(a.energy / Math.max(1, a.genes.repro), 0.15, 1.35);
            const alpha = 0.42 + Math.min(0.5, readiness * 0.4);
            const wing = Math.max(2.5, base * 0.72);
            const bob = Math.sin(t * 2.1 + a.x * 0.31 + a.y * 0.17) * 0.45;
            ctx.save();
            ctx.translate(px, py + bob);
            ctx.rotate(a.heading || 0);
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            ctx.strokeStyle = rgba(PALETTE.preyRgb, alpha);
            ctx.lineWidth = Math.max(0.55, base * 0.095);
            ctx.beginPath();
            ctx.moveTo(-wing * 0.62, 0);
            ctx.quadraticCurveTo(-wing * 0.08, -wing * 0.58, wing * 0.84, -wing * 0.31);
            ctx.moveTo(-wing * 0.62, 0);
            ctx.quadraticCurveTo(-wing * 0.08, wing * 0.58, wing * 0.84, wing * 0.31);
            ctx.moveTo(-wing * 0.55, 0);
            ctx.lineTo(wing * 0.72, 0);
