            ctx.fillStyle = rgba('242,220,172', Math.min(0.95, alpha + 0.17));
            ctx.beginPath();
            ctx.arc(wing * 0.73, 0, Math.max(0.55, base * 0.085), 0, TAU);
            ctx.fill();
            if (a.energy >= a.genes.repro && a.reproCooldown <= 0) {
              ctx.strokeStyle = rgba(PALETTE.preyRgb, 0.28);
