            if (!a.alive) continue;
            const px = (a.x + 0.5) * sx;
            const py = (a.y + 0.5) * sy;
            const size = Math.max(3.9, base * 1.12);
            const alpha = 0.65 + Math.min(0.28, a.energy / Math.max(1, a.genes.repro));
            const stride = Math.sin(t * 2.9 + a.x * 0.43 + a.y * 0.2) * size * 0.16;
            ctx.save();
            ctx.translate(px, py);
            ctx.rotate((a.heading || 0) + Math.PI / 2);
            ctx.strokeStyle = rgba(PALETTE.predatorRgb, alpha);
            ctx.fillStyle = rgba(PALETTE.predatorRgb, alpha);
            ctx.lineWidth = Math.max(0.65, base * 0.105);
            ctx.lineCap = 'round';
            // Four paired legs.
            for (let leg = 0; leg < 4; leg++) {
              const along = (leg - 1.5) * size * 0.27;
              const spread = size * (0.55 + leg * 0.06) + stride * (leg % 2 ? -1 : 1);
              ctx.beginPath();
              ctx.moveTo(-size * 0.12, along);
              ctx.quadraticCurveTo(-spread * 0.55, along - size * 0.3, -spread, along - size * 0.05);
              ctx.moveTo(size * 0.12, along);
              ctx.quadraticCurveTo(spread * 0.55, along + size * 0.3, spread, along + size * 0.05);
              ctx.stroke();
            }
            // Cephalothorax and abdomen, cut as a lantern-shaped diamond.
            ctx.beginPath();
            ctx.moveTo(0, -size * 0.78);
            ctx.lineTo(size * 0.45, 0);
            ctx.lineTo(0, size * 0.78);
            ctx.lineTo(-size * 0.45, 0);
            ctx.closePath();
            ctx.stroke();
            ctx.beginPath();
            ctx.arc(0, -size * 0.23, Math.max(0.8, size * 0.15), 0, TAU);
            ctx.fill();
            if (a.energy >= a.genes.repro) {
              ctx.strokeStyle = rgba(PALETTE.predatorRgb, 0.28);
              ctx.lineWidth = 0.55;
              ctx.beginPath();
              ctx.arc(0, 0, size * 0.95, 0, TAU);
              ctx.stroke();
            }
            ctx.restore();
          }
          ctx.restore();
        }

        drawEffects(now) {
          const { ctx, sx, sy, w, h } = this;
          const base = Math.min(sx, sy);
          if (!this.effects.length) return;
          const active = [];
          ctx.save();
          ctx.globalCompositeOperation = 'lighter';
          for (const fx of this.effects) {
            const progress = (now - fx.born) / fx.ttl;
            if (progress >= 1) continue;
            active.push(fx);
            const px = (fx.x + 0.5) * sx;
            const py = (fx.y + 0.5) * sy;
            const fade = 1 - progress;
            if (fx.kind === 'graze') {
              ctx.fillStyle = rgba(PALETTE.plantRgb, fade * 0.38);
              ctx.beginPath();
              ctx.arc(px + fx.dx * progress * 7, py + fx.dy * progress * 7 - progress * 4, 0.9 + progress * 1.7, 0, TAU);
              ctx.fill();
            } else if (fx.kind === 'birth') {
              const speciesColor = fx.meta.species === 'predator' ? PALETTE.predatorRgb : PALETTE.preyRgb;
              const ring = 2 + progress * base * 2.1;
              ctx.strokeStyle = rgba(speciesColor, fade * 0.42);
              ctx.lineWidth = 0.7;
              ctx.beginPath();
              ctx.arc(px, py, ring, 0, TAU);
              ctx.stroke();
            } else if (fx.kind === 'kill' || fx.kind === 'feed') {
              const ring = 2 + progress * base * 3.4;
              ctx.strokeStyle = fx.kind === 'kill' ? rgba(PALETTE.predatorRgb, fade * 0.55) : rgba(PALETTE.preyRgb, fade * 0.28);
              ctx.lineWidth = 0.8;
              ctx.beginPath();
              ctx.arc(px, py, ring, 0, TAU);
              ctx.stroke();
              if (fx.kind === 'kill') {
                for (let i = 0; i < 4; i++) {
                  const angle = fx.seed * TAU + i * 1.57;
                  ctx.fillStyle = rgba(PALETTE.predatorRgb, fade * 0.42);
                  ctx.fillRect(px + Math.cos(angle) * ring - 0.6, py + Math.sin(angle) * ring - 0.6, 1.2, 1.2);
                }
              }
            } else if (fx.kind === 'blight') {
              ctx.fillStyle = rgba('177,140,155', fade * 0.26);
              ctx.beginPath();
              ctx.arc(px, py, 2.2 + progress * base * 1.3, 0, TAU);
              ctx.fill();
            } else if (fx.kind === 'starve' || fx.kind === 'pass') {
              ctx.strokeStyle = fx.meta.species === 'predator' ? rgba(PALETTE.predatorRgb, fade * 0.24) : rgba(PALETTE.preyRgb, fade * 0.2);
              ctx.lineWidth = 0.7;
              const s = 1.2 + progress * 2.8;
              ctx.beginPath();
              ctx.moveTo(px - s, py - s);
              ctx.lineTo(px + s, py + s);
              ctx.moveTo(px + s, py - s);
              ctx.lineTo(px - s, py + s);
              ctx.stroke();
            } else if (fx.kind === 'weather') {
              const color = fx.meta.color || PALETTE.drought;
              const rgb = color.replace('#', '').match(/.{2}/g).map(v => parseInt(v, 16)).join(',');
              for (let ring = 0; ring < 2; ring++) {
                const rr = Math.min(w, h) * (0.08 + progress * (0.33 + ring * 0.08));
                ctx.strokeStyle = `rgba(${rgb},${fade * (0.18 - ring * 0.06)})`;
                ctx.lineWidth = 0.8;
                ctx.beginPath();
                ctx.ellipse(w * 0.52, h * 0.47, rr * 1.2, rr * 0.78, 0, 0, TAU);
                ctx.stroke();
              }
            }
          }
          ctx.restore();
          this.effects = active;
        }

        drawEdgeMarks() {
          const { ctx, w, h } = this;
          ctx.save();
          ctx.strokeStyle = 'rgba(225,214,186,.18)';
          ctx.lineWidth = 0.6;
          ctx.beginPath();
          ctx.moveTo(17, 17); ctx.lineTo(17, 27); ctx.moveTo(17, 17); ctx.lineTo(27, 17);
          ctx.moveTo(w - 17, 17); ctx.lineTo(w - 17, 27); ctx.moveTo(w - 17, 17); ctx.lineTo(w - 27, 17);
          ctx.moveTo(17, h - 17); ctx.lineTo(17, h - 27); ctx.moveTo(17, h - 17); ctx.lineTo(27, h - 17);
          ctx.moveTo(w - 17, h - 17); ctx.lineTo(w - 17, h - 27); ctx.moveTo(w - 17, h - 17); ctx.lineTo(w - 27, h - 17);
          ctx.stroke();
          // A few hairline scale ticks, barely visible.
          ctx.strokeStyle = 'rgba(225,214,186,.14)';
          for (let i = 0; i < 7; i++) {
            const y = 52 + i * 9;
            ctx.beginPath();
            ctx.moveTo(w - 14, y);
            ctx.lineTo(w - (i % 2 ? 9 : 18), y);
            ctx.stroke();
          }
          ctx.restore();
        }
      }

      window.NocturneView = VivariumView;
    })();
  </script>

