app=r'''  <script>
    /* ============================================================
       III. THE INSTRUMENTS AND THE CLOSING REPORT
       ============================================================ */
    (() => {
      'use strict';
      const N = window.Nocturne;
      const { CATASTROPHE_META, DEFAULTS } = N;
      const TAU = Math.PI * 2;
      const MIN_HORIZON = 4;
      const MAX_HORIZON = 120;
      const BASE_CYCLES_PER_SECOND = 45;
      const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const formatter = new Intl.NumberFormat('en-US');
      const eventInk = { drought: '#8e6b36', plague: '#865f70', frost: '#5f7b84' };

      const state = {
        seed: DEFAULTS.seed,
        mutation: DEFAULTS.mutation,
        regrowth: DEFAULTS.regrowth,
        horizon: DEFAULTS.horizon,
        tempo: DEFAULTS.tempo,
        events: {
          drought: { enabled: DEFAULTS.events.drought.enabled, interval: DEFAULTS.events.drought.interval },
          plague: { enabled: DEFAULTS.events.plague.enabled, interval: DEFAULTS.events.plague.interval },
          frost: { enabled: DEFAULTS.events.frost.enabled, interval: DEFAULTS.events.frost.interval }
        },
        running: true,
        reportOpen: false,
        finishScheduled: false
      };

      const el = {};
      let sim = null;
      let view = null;
      let lastFrame = 0;
      let accumulator = 0;
      let lastHudUpdate = 0;
      let finishTimer = 0;
      let tintTimer = 0;
      let bannerTimer = 0;
      let bannerBusy = false;
      let bannerQueue = [];
      let sparkRaf = 0;
      let resizeRaf = 0;
      let tipTarget = null;
      let tipTimer = 0;
      let chartHoverIndex = null;
      let chartMetrics = null;

      init();

      function init() {
        cacheDOM();
        setupDialTicks();
        syncControls();
        setupListeners();
        setupTooltips();
        startSimulation(true);
        setupResizeObservers();
        requestAnimationFrame(() => {
          updateSparks();
          view.resize();
          view.draw(performance.now());
        });
        requestAnimationFrame(loop);
        exposeDebugApi();
      }

      function cacheDOM() {
        const ids = [
          'appShell', 'world', 'chamber', 'statusText', 'headSeed', 'headEpoch', 'headCycles',
          'cycleReadout', 'nightReadout', 'condition', 'conditionText', 'eventBanner',
          'eventKind', 'eventNo', 'eventTitle', 'eventCopy', 'plantCount', 'preyCount', 'predCount',
          'playButton', 'playIcon', 'stepButton', 'restartButton', 'genReadout', 'tickReadout',
          'timeline', 'timelineFill', 'timelineEvents', 'nextEvent', 'tempoChip',
          'seedInput', 'seedDown', 'seedUp', 'seedNew', 'sparkSeed',
          'mutationRange', 'mutationValue', 'sparkMutation',
          'regrowthRange', 'regrowthValue', 'sparkRegrowth',
          'horizonDown', 'horizonUp', 'horizonValue', 'sparkHorizon',
          'tempoDial', 'tempoValue', 'dialNumber', 'dialKnob', 'dialTicks', 'sparkTempo',
          'sparkDrought', 'sparkPlague', 'sparkFrost', 'droughtInterval', 'plagueInterval', 'frostInterval',
          'tint', 'openReportButton', 'toolTip',
          'report', 'reportTitle', 'reportNarrative', 'stampGen', 'stampSeed', 'metaSeed',
          'metaConditions', 'metaHorizon', 'metaDisturbances', 'metaFinal', 'statPrey', 'statPred',
          'statMoss', 'statEvents', 'eventLedger', 'ledgerFoot', 'reportClosing',
          'inspectButton', 'rerunButton', 'newSeedButton', 'footerInspect',
          'populationChart', 'chartTip', 'traitSpeed', 'traitVision', 'traitMetabolism', 'traitRepro'
        ];
        for (const id of ids) el[id] = document.getElementById(id);
        el.consoleScroll = document.querySelector('.console-scroll');
        el.eventControls = [...document.querySelectorAll('.event-control')];
        el.eventSwitches = [...document.querySelectorAll('.event-switch')];
        el.eventStepButtons = [...document.querySelectorAll('[data-event-down], [data-event-up]')];
        el.traitCanvases = {
          speed: el.traitSpeed,
          vision: el.traitVision,
          metabolism: el.traitMetabolism,
          repro: el.traitRepro
        };
      }

      function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
      function pad(value, size = 2) { return String(value).padStart(size, '0'); }
      function setText(node, text) { if (node && node.textContent !== text) node.textContent = text; }
      function ink(alpha) { return `rgba(32,38,30,${alpha})`; }
      function speciesColor(species, alpha = 1) {
        return species === 'prey' ? `rgba(225,190,127,${alpha})` : `rgba(201,113,85,${alpha})`;
      }

      function currentConfig() {
        return {
          seed: state.seed,
          mutation: state.mutation,
          regrowth: state.regrowth,
          horizon: state.horizon,
          events: {
            drought: { ...state.events.drought },
            plague: { ...state.events.plague },
            frost: { ...state.events.frost }
          }
        };
      }

      function startSimulation(autoplay = true) {
        clearTimeout(finishTimer);
        finishTimer = 0;
        state.finishScheduled = false;
        hideBanner(true);
        bannerQueue = [];
        el.appShell.classList.remove('is-finished', 'is-paused');
        el.report.classList.remove('is-open');
        el.report.setAttribute('aria-hidden', 'true');
        el.appShell.inert = false;
        document.body.style.overflow = '';
        state.reportOpen = false;
        el.openReportButton.hidden = true;

        sim = new N.VivariumEngine({ ...currentConfig(), hooks: {} });
        sim.hooks = {
          onEffect(kind, x, y, meta) {
            if (view) view.addEffect(kind, x, y, meta);
          },
          onCatastrophe(record, meta) {
            handleCatastrophe(record, meta);
          },
          onFinish() {
            scheduleCompletion();
          },
          onGeneration() {
            updateEventMarkers();
          }
        };

        if (!view) {
          view = new window.NocturneView(el.world, sim);
        } else {
          view.reseed(sim);
          view.resize();
        }
        view.clearEffects();

        state.running = !sim.finished && autoplay;
        accumulator = 0;
        lastFrame = performance.now();
        syncControls();
        drawAllSparks();
        updateEventMarkers();
        updatePlayButton();
        updateHUD(true);
      }

      function syncControls() {
        el.seedInput.value = N.formatSeed(state.seed);
        setText(el.headSeed, N.formatSeed(state.seed));

        el.mutationRange.value = String(state.mutation);
        el.mutationRange.style.setProperty('--fill', `${state.mutation / 30 * 100}%`);
        el.mutationRange.setAttribute('aria-valuetext', `${state.mutation.toFixed(1)} percent per birth`);
        el.mutationValue.innerHTML = `${state.mutation.toFixed(1)} <span class="unit">% / birth</span>`;

        el.regrowthRange.value = String(Math.round(state.regrowth * 100));
        el.regrowthRange.style.setProperty('--fill', `${(state.regrowth - 0.2) / 2.2 * 100}%`);
        el.regrowthRange.setAttribute('aria-valuetext', `${state.regrowth.toFixed(2)} times baseline regrowth`);
        el.regrowthValue.innerHTML = `${state.regrowth.toFixed(2)} <span class="unit">× / cycle</span>`;

        setText(el.horizonValue, String(state.horizon));
        setText(el.tempoValue.innerHTML ? el.tempoValue : null, '');
        el.tempoValue.innerHTML = `×${state.tempo.toFixed(1)} <span class="unit">real time</span>`;
        setText(el.dialNumber, state.tempo.toFixed(1));
        el.tempoDial.setAttribute('aria-valuenow', String(state.tempo));
        el.tempoDial.setAttribute('aria-valuetext', `Tempo times ${state.tempo.toFixed(1)}`);
        setText(el.tempoChip, `tempo ×${state.tempo.toFixed(1)}`);

        for (const key of Object.keys(state.events)) {
          const eventState = state.events[key];
          const switchButton = el.eventSwitches.find(b => b.dataset.kind === key);
          const control = el.eventControls.find(c => c.dataset.kind === key);
          const intervalOutput = el[`${key}Interval`];
          if (switchButton) switchButton.setAttribute('aria-checked', String(eventState.enabled));
          if (control) control.classList.toggle('is-off', !eventState.enabled);
          setText(intervalOutput, String(eventState.interval));
        }
        updateDialVisual();
      }

      function setupDialTicks() {
        if (!el.dialTicks) return;
        const namespace = 'http://www.w3.org/2000/svg';
        for (let i = 0; i <= 28; i++) {
          const angle = (135 + (i / 28) * 270) * Math.PI / 180;
          const major = i % 4 === 0;
          const inner = major ? 41.5 : 43.5;
          const outer = 47;
          const line = document.createElementNS(namespace, 'line');
          line.setAttribute('x1', (50 + Math.cos(angle) * inner).toFixed(2));
          line.setAttribute('y1', (50 + Math.sin(angle) * inner).toFixed(2));
          line.setAttribute('x2', (50 + Math.cos(angle) * outer).toFixed(2));
          line.setAttribute('y2', (50 + Math.sin(angle) * outer).toFixed(2));
          line.setAttribute('stroke-width', major ? '0.9' : '0.5');
          line.setAttribute('stroke-opacity', major ? '0.62' : '0.3');
          el.dialTicks.appendChild(line);
        }
      }

      function updateDialVisual() {
        if (!el.dialKnob || !el.tempoDial) return;
        const normalized = (state.tempo - 1) / 11;
        const angle = (135 + normalized * 270) * Math.PI / 180;
        el.dialKnob.setAttribute('cx', (50 + Math.cos(angle) * 37).toFixed(2));
        el.dialKnob.setAttribute('cy', (50 + Math.sin(angle) * 37).toFixed(2));
      }

      function setupListeners() {
        el.mutationRange.addEventListener('input', () => {
          state.mutation = Number(el.mutationRange.value);
          el.mutationRange.style.setProperty('--fill', `${state.mutation / 30 * 100}%`);
          el.mutationRange.setAttribute('aria-valuetext', `${state.mutation.toFixed(1)} percent per birth`);
          el.mutationValue.innerHTML = `${state.mutation.toFixed(1)} <span class="unit">% / birth</span>`;
          sim.setMutation(state.mutation);
          drawSpark(el.sparkMutation, 'mutation');
        });

        el.regrowthRange.addEventListener('input', () => {
          state.regrowth = Number(el.regrowthRange.value) / 100;
          el.regrowthRange.style.setProperty('--fill', `${(state.regrowth - 0.2) / 2.2 * 100}%`);
          el.regrowthRange.setAttribute('aria-valuetext', `${state.regrowth.toFixed(2)} times baseline regrowth`);
          el.regrowthValue.innerHTML = `${state.regrowth.toFixed(2)} <span class="unit">× / cycle</span>`;
          sim.setRegrowth(state.regrowth);
          drawSpark(el.sparkRegrowth, 'regrowth');
        });

        el.seedInput.addEventListener('change', commitSeedInput);
        el.seedInput.addEventListener('keydown', (event) => {
          if (event.key === 'Enter') {
            event.preventDefault();
            commitSeedInput();
            el.seedInput.blur();
          }
        });
        el.seedDown.addEventListener('click', () => changeSeed(-1));
        el.seedUp.addEventListener('click', () => changeSeed(1));
        el.seedNew.addEventListener('click', () => {
          state.seed = N.deriveSeed(state.seed);
          restartRun(true);
        });

        el.horizonDown.addEventListener('click', () => setHorizon(state.horizon - 1));
        el.horizonUp.addEventListener('click', () => setHorizon(state.horizon + 1));

        el.playButton.addEventListener('click', () => setRunning(!state.running));
        el.stepButton.addEventListener('click', stepOnce);
        el.restartButton.addEventListener('click', () => restartRun(true));

        setupDialEvents();

        el.eventSwitches.forEach(button => {
          button.addEventListener('click', () => {
            const key = button.dataset.kind;
            const next = button.getAttribute('aria-checked') !== 'true';
            state.events[key].enabled = next;
            button.setAttribute('aria-checked', String(next));
            const control = el.eventControls.find(c => c.dataset.kind === key);
            if (control) control.classList.toggle('is-off', !next);
            sim.setEventEnabled(key, next);
            drawAllSparks();
            updateHUD(true);
          });
        });

        el.eventStepButtons.forEach(button => {
          button.addEventListener('click', () => {
            const key = button.dataset.eventDown || button.dataset.eventUp;
            const direction = button.dataset.eventDown ? -1 : 1;
            const next = clamp(state.events[key].interval + direction, 3, 30);
            state.events[key].interval = next;
            setText(el[`${key}Interval`], String(next));
            sim.setEventInterval(key, next);
            drawAllSparks();
            updateHUD(true);
          });
        });

        el.inspectButton.addEventListener('click', closeReport);
        el.footerInspect.addEventListener('click', closeReport);
        el.rerunButton.addEventListener('click', () => {
          closeReport(false);
          restartRun(true);
        });
        el.newSeedButton.addEventListener('click', () => {
          state.seed = N.deriveSeed(state.seed);
          closeReport(false);
          restartRun(true);
        });
        el.openReportButton.addEventListener('click', openReport);

        window.addEventListener('keydown', handleGlobalKeys);
        window.addEventListener('resize', onWindowResize, { passive: true });
        window.addEventListener('scroll', hideTip, { passive: true, capture: true });
        document.addEventListener('visibilitychange', () => {
          if (!document.hidden) lastFrame = performance.now();
        });
        el.populationChart.addEventListener('pointermove', handleChartPointerMove);
        el.populationChart.addEventListener('pointerleave', handleChartPointerLeave);
      }

      function setupDialEvents() {
        let drag = null;
        el.tempoDial.addEventListener('pointerdown', (event) => {
          if (event.button !== 0) return;
          drag = { y: event.clientY, value: state.tempo };
          el.tempoDial.setPointerCapture(event.pointerId);
          event.preventDefault();
        });
        el.tempoDial.addEventListener('pointermove', (event) => {
          if (!drag) return;
          const delta = (drag.y - event.clientY) / 92 * 11;
          setTempo(drag.value + delta);
          event.preventDefault();
        });
        const endDrag = () => {
          if (!drag) return;
          drag = null;
          updateHUD(true);
        };
        el.tempoDial.addEventListener('pointerup', endDrag);
        el.tempoDial.addEventListener('pointercancel', endDrag);
        el.tempoDial.addEventListener('keydown', (event) => {
          let next = state.tempo;
          if (event.key === 'ArrowUp' || event.key === 'ArrowRight') next += 0.5;
          else if (event.key === 'ArrowDown' || event.key === 'ArrowLeft') next -= 0.5;
          else if (event.key === 'PageUp') next += 2;
          else if (event.key === 'PageDown') next -= 2;
          else if (event.key === 'Home') next = 1;
          else if (event.key === 'End') next = 12;
          else return;
          event.preventDefault();
          setTempo(next);
        });
        el.tempoDial.addEventListener('dblclick', () => setTempo(4));
      }

      function handleGlobalKeys(event) {
        const tag = event.target.tagName;
        const isField = tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'BUTTON' || event.target.isContentEditable;
        if (event.key === 'Escape' && state.reportOpen) {
          event.preventDefault();
          closeReport();
          return;
        }
        if (isField || event.metaKey || event.ctrlKey || event.altKey) return;
        if (event.code === 'Space') {
          event.preventDefault();
          setRunning(!state.running);
        } else if (event.key === '.') {
          event.preventDefault();
          stepOnce();
        } else if (event.key === 'r' || event.key === 'R') {
          event.preventDefault();
          restartRun(true);
        }
      }

      function commitSeedInput() {
        const next = N.normalizeSeed(el.seedInput.value);
        el.seedInput.value = N.formatSeed(next);
        if (next === state.seed) return;
        state.seed = next;
        restartRun(true);
      }

      function changeSeed(direction) {
        state.seed = N.normalizeSeed(state.seed + direction);
        restartRun(true);
      }

      function setHorizon(next) {
        state.horizon = clamp(Math.round(next), MIN_HORIZON, MAX_HORIZON);
        setText(el.horizonValue, String(state.horizon));
        sim.setHorizon(state.horizon);
        updateEventMarkers();
        drawAllSparks();
        updateHUD(true);
        if (sim.finished) scheduleCompletion();
      }

      function setTempo(value) {
        state.tempo = clamp(Math.round(value * 2) / 2, 1, 12);
        el.tempoValue.innerHTML = `×${state.tempo.toFixed(1)} <span class="unit">real time</span>`;
        setText(el.dialNumber, state.tempo.toFixed(1));
        setText(el.tempoChip, `tempo ×${state.tempo.toFixed(1)}`);
        el.tempoDial.setAttribute('aria-valuenow', String(state.tempo));
        el.tempoDial.setAttribute('aria-valuetext', `Tempo times ${state.tempo.toFixed(1)}`);
        updateDialVisual();
        drawSpark(el.sparkTempo, 'tempo');
        updateHUD(true);
      }

      function setRunning(next) {
        if (!sim) return;
        if (next && sim.finished) {
          openReport();
          return;
        }
        state.running = Boolean(next) && !sim.finished;
        accumulator = 0;
        lastFrame = performance.now();
        el.appShell.classList.toggle('is-paused', !state.running && !sim.finished);
        updatePlayButton();
        updateHUD(true);
      }

      function stepOnce() {
        if (!sim) return;
        if (sim.finished) { openReport(); return; }
        state.running = false;
        el.appShell.classList.add('is-paused');
        accumulator = 0;
        sim.step();
        if (sim.finished) scheduleCompletion();
        updatePlayButton();
        updateHUD(true);
      }

      function restartRun(autoplay = true) {
        closeReport(false);
        startSimulation(autoplay);
      }

      function scheduleCompletion() {
        if (!sim || !sim.finished || state.finishScheduled) return;
        state.finishScheduled = true;
        state.running = false;
        accumulator = 0;
        el.appShell.classList.remove('is-paused');
        el.appShell.classList.add('is-finished');
        updatePlayButton();
        updateHUD(true);
        setText(el.statusText, 'Specimen closed');
        el.openReportButton.hidden = true;
        clearTimeout(finishTimer);
        finishTimer = window.setTimeout(() => {
          if (sim && sim.finished) openReport();
        }, reducedMotion ? 300 : 1000);
      }

      function updatePlayButton() {
        const running = state.running && !sim.finished;
        el.playButton.disabled = sim.finished;
        el.stepButton.disabled = sim.finished;
        el.playButton.setAttribute('aria-label', sim.finished ? 'Observation complete' : running ? 'Pause the succession' : 'Resume the succession');
        el.playIcon.innerHTML = running
          ? '<path d="M3.4 2.4h2.3v9.2H3.4zM8.3 2.4h2.3v9.2H8.3z"/>'
          : '<path d="M4 2.5v9L11.5 7 4 2.5Z"/>';
      }

      function updateHUD(force = false) {
        if (!sim) return;
        const now = performance.now();
        if (!force && now - lastHudUpdate < 140) return;
        lastHudUpdate = now;
        const stats = sim.summaryStats();
        const active = sim.activeList;
        const horizon = sim.settings.horizon;

        setText(el.headEpoch, `${pad(sim.generation)} / ${pad(horizon)}`);
        setText(el.headCycles, pad(sim.tick, 6));
        setText(el.cycleReadout, pad(sim.tick, 4));
        setText(el.genReadout, `${pad(sim.generation)} / ${pad(horizon)}`);
        setText(el.tickReadout, `${pad(sim.tick, 4)} cycles`);
        setText(el.headSeed, N.formatSeed(state.seed));
        setText(el.plantCount, `${Math.round(stats.cover * 100)}%`);
        setText(el.preyCount, formatter.format(stats.prey));
        setText(el.predCount, formatter.format(stats.predator));
        setText(el.nightReadout, `${nightName(sim.generation)} / gen ${pad(sim.generation)}`);
        setText(el.statusText, sim.finished ? 'Specimen closed' : state.running ? 'Under observation' : 'Held in glass');

        const withinGeneration = sim.finished ? 0 : (sim.tick % N.CYCLES_PER_GENERATION) / N.CYCLES_PER_GENERATION;
        const progress = clamp((sim.generation + withinGeneration) / Math.max(1, horizon) * 100, 0, 100);
        el.timelineFill.style.width = `${progress}%`;
        el.timeline.setAttribute('aria-valuemax', String(horizon));
        el.timeline.setAttribute('aria-valuenow', String(Math.min(sim.generation, horizon)));
        el.timeline.setAttribute('aria-valuetext', `${sim.generation} of ${horizon} generations`);

        if (!sim.finished) {
          const next = sim.nextScheduledEvent();
          setText(el.nextEvent, next ? `Next event / ${next.label} · G${pad(next.at)}` : 'Next event / none');
        } else {
          setText(el.nextEvent, 'Chamber closed');
        }

        if (active.length) {
          const condition = active[active.length - 1];
          const remaining = Math.max(0, Math.ceil((condition.endTick - sim.tick) / N.CYCLES_PER_GENERATION * 10) / 10);
          const names = active.map(c => CATASTROPHE_META[c.key].label).join(' + ').toUpperCase();
          el.condition.style.setProperty('--condition-color', condition.color);
          setText(el.conditionText, `${names} · ${remaining.toFixed(1)} gen`);
          el.condition.classList.add('is-live');
        } else {
          el.condition.classList.remove('is-live');
        }

        updateEventMarkers();
        el.openReportButton.hidden = !(sim.finished && !state.reportOpen);
        if (sim.finished && state.reportOpen) el.openReportButton.hidden = true;
      }

      function nightName(generation) {
        const phases = ['after nightfall', 'deep night', 'the hollow hours', 'before dawn'];
        return phases[generation % phases.length];
      }

      function updateEventMarkers() {
        if (!sim || !el.timelineEvents) return;
        const horizon = Math.max(1, sim.settings.horizon);
        el.timelineEvents.replaceChildren();
        for (const record of sim.catastrophes) {
          const percent = clamp(record.generation / horizon * 100, 0.4, 99.6);
          const marker = document.createElement('span');
          marker.className = 'run-event';
          marker.style.left = `${percent}%`;
          marker.style.setProperty('--event-color', record.color);
          marker.dataset.tip = `${record.label} · generation ${pad(record.generation)} — ${eventEffectCopy(record)}`;
          marker.setAttribute('aria-hidden', 'true');
          el.timelineEvents.appendChild(marker);
        }
      }

      function eventEffectCopy(record) {
        if (record.key === 'plague') {
          const count = record.toll.prey + record.toll.predator;
          return `${count} creature${count === 1 ? '' : 's'} lost to the blight.`;
        }
        const count = record.toll.plants;
        return `${formatter.format(count)} moss cells withered.`;
      }

      function handleCatastrophe(record, meta) {
        bannerQueue.push({ record, meta });
        if (!bannerBusy && !state.reportOpen) showNextBanner();
        if (view) view.addEffect('weather', Math.floor(N.WORLD.width / 2), Math.floor(N.WORLD.height / 2), { color: meta.color });
        updateEventMarkers();
        updateHUD(true);
      }

      function showNextBanner() {
        if (bannerBusy || state.reportOpen || !bannerQueue.length) return;
        bannerBusy = true;
        const { record, meta } = bannerQueue.shift();
        el.eventKind.textContent = `Disturbance ${meta.order} · ${meta.label}`;
        el.eventNo.textContent = `No. ${pad(record.id)} / gen ${pad(record.generation)}`;
        el.eventTitle.textContent = meta.title;
        el.eventCopy.textContent = meta.copy;
        el.eventBanner.style.setProperty('--event-ink', eventInk[record.key] || 'var(--rust-ink)');
        el.eventBanner.classList.add('is-visible');

        el.tint.style.setProperty('--tint-color', meta.colorSoft);
        el.tint.classList.add('is-live');
        clearTimeout(tintTimer);
        tintTimer = window.setTimeout(() => el.tint.classList.remove('is-live'), reducedMotion ? 250 : 1700);

        clearTimeout(bannerTimer);
        bannerTimer = window.setTimeout(() => {
          el.eventBanner.classList.remove('is-visible');
          bannerTimer = window.setTimeout(() => {
            bannerBusy = false;
            showNextBanner();
          }, 420);
        }, reducedMotion ? 1800 : 3600);
      }

      function hideBanner(clearQueue = false) {
        clearTimeout(bannerTimer);
        clearTimeout(tintTimer);
        el.eventBanner?.classList.remove('is-visible');
        el.tint?.classList.remove('is-live');
        bannerBusy = false;
        if (clearQueue) bannerQueue = [];
      }

      function loop(now) {
        if (!lastFrame) lastFrame = now;
        const delta = Math.min(0.12, Math.max(0, (now - lastFrame) / 1000));
        lastFrame = now;
        if (!state.reportOpen) {
          if (state.running && sim && !sim.finished) {
            accumulator += delta * BASE_CYCLES_PER_SECOND * state.tempo;
            let steps = 0;
            const ceiling = reducedMotion ? 100 : 90;
            while (accumulator >= 1 && steps < ceiling && !sim.finished) {
              sim.step();
              accumulator -= 1;
              steps += 1;
            }
            if (steps >= ceiling) accumulator = 0;
            if (sim.finished) {
              accumulator = 0;
              if (!state.finishScheduled) scheduleCompletion();
            }
          } else {
            accumulator = 0;
          }
          view?.draw(now);
          updateHUD();
        } else {
          accumulator = 0;
        }
        requestAnimationFrame(loop);
      }

      function setupResizeObservers() {
        if ('ResizeObserver' in window) {
          const observer = new ResizeObserver(() => {
            cancelAnimationFrame(resizeRaf);
            resizeRaf = requestAnimationFrame(() => {
              view?.resize();
              drawAllSparks();
              if (state.reportOpen) drawCharts();
            });
          });
          observer.observe(el.chamber);
          observer.observe(el.consoleScroll || el.appShell);
        }
        window.addEventListener('resize', onWindowResize, { passive: true });
      }

      function onWindowResize() {
        cancelAnimationFrame(resizeRaf);
        resizeRaf = requestAnimationFrame(() => {
          view?.resize();
          drawAllSparks();
          if (state.reportOpen) drawCharts();
        });
      }

      function updateSparks() {
        cancelAnimationFrame(sparkRaf);
        sparkRaf = requestAnimationFrame(drawAllSparks);
      }

      function drawAllSparks() {
        drawSpark(el.sparkSeed, 'seed');
        drawSpark(el.sparkMutation, 'mutation');
        drawSpark(el.sparkRegrowth, 'regrowth');
        drawSpark(el.sparkHorizon, 'horizon');
        drawSpark(el.sparkTempo, 'tempo');
        drawSpark(el.sparkDrought, 'event', 'drought');
        drawSpark(el.sparkPlague, 'event', 'plague');
        drawSpark(el.sparkFrost, 'event', 'frost');
      }

      function fitSpark(canvas) {
        if (!canvas) return null;
        const rect = canvas.getBoundingClientRect();
        if (!rect.width || !rect.height) return null;
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        const pixelWidth = Math.round(rect.width * dpr);
        const pixelHeight = Math.round(rect.height * dpr);
        if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
          canvas.width = pixelWidth;
          canvas.height = pixelHeight;
        }
        const ctx = canvas.getContext('2d');
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.clearRect(0, 0, rect.width, rect.height);
        return { ctx, w: rect.width, h: rect.height };
      }

      function drawSpark(canvas, kind, key = null) {
        const fit = fitSpark(canvas);
        if (!fit) return;
        const { ctx, w, h } = fit;
        const mid = h / 2;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        ctx.strokeStyle = ink(0.12);
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(0, h - 0.5);
        ctx.lineTo(w, h - 0.5);
        ctx.stroke();

        if (kind === 'seed') {
          const seed = state.seed;
          let s = (seed ^ 0x9e3779b9) >>> 0 || 1;
          const points = [];
          for (let x = 0; x <= w; x += 1.5) {
            s ^= s << 13; s ^= s >>> 17; s ^= s << 5;
            const y = mid + ((s >>> 0) / 4294967296 - 0.5) * h * 0.64;
            points.push([x, y]);
          }
          ctx.strokeStyle = 'rgba(95,101,85,.54)';
          ctx.lineWidth = 0.65;
          ctx.beginPath();
          points.forEach(([x, y], index) => index ? ctx.lineTo(x, y) : ctx.moveTo(x, y));
          ctx.stroke();
          ctx.fillStyle = 'rgba(155,77,56,.7)';
          ctx.beginPath();
          ctx.arc(w / 2, mid, 1.25, 0, TAU);
          ctx.fill();
        } else if (kind === 'mutation') {
          const spread = Math.max(0.08, state.mutation / 30);
          for (let line = 0; line < 3; line++) {
            ctx.strokeStyle = line === 1 ? 'rgba(95,101,85,.48)' : ink(0.18 + line * 0.045);
            ctx.lineWidth = 0.6;
            ctx.beginPath();
            for (let x = 0; x <= w; x += 2) {
              const t = x / Math.max(1, w);
              const y = mid + Math.sin(x * 0.38 + line * 2.1 + state.seed) * h * 0.3 * spread * t;
              if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.stroke();
          }
          ctx.fillStyle = 'rgba(155,77,56,.65)';
          ctx.fillRect(w - 1.5, mid - h * 0.3 * spread, 1.5, h * 0.6 * spread);
        } else if (kind === 'regrowth') {
          const strength = (state.regrowth - 0.2) / 2.2;
          ctx.strokeStyle = 'rgba(102,119,68,.72)';
          ctx.lineWidth = 0.75;
          ctx.beginPath();
          for (let x = 0; x <= w; x += 1.5) {
            const t = x / Math.max(1, w);
            const y = h - 2 - (h - 5) * (1 - Math.exp(-t * (1.2 + strength * 4.4)));
            if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
          }
          ctx.stroke();
          ctx.lineTo(w, h - 1);
          ctx.lineTo(0, h - 1);
          ctx.closePath();
          ctx.fillStyle = 'rgba(102,119,68,.1)';
          ctx.fill();
          ctx.strokeStyle = ink(0.13);
          ctx.lineWidth = 0.45;
          ctx.setLineDash([1.5, 2.5]);
          ctx.beginPath();
          ctx.moveTo(0, 3);
          ctx.lineTo(w, 3);
          ctx.stroke();
          ctx.setLineDash([]);
        } else if (kind === 'horizon') {
          const end = 2 + (state.horizon / MAX_HORIZON) * (w - 4);
          ctx.strokeStyle = ink(0.2);
          ctx.lineWidth = 0.55;
          for (let g = 0; g <= MAX_HORIZON; g += 10) {
            const x = 2 + (g / MAX_HORIZON) * (w - 4);
            const tall = g % 30 === 0 ? 5 : 2.7;
            ctx.beginPath();
            ctx.moveTo(x, h - 2);
            ctx.lineTo(x, h - 2 - tall);
            ctx.stroke();
          }
          ctx.strokeStyle = 'rgba(95,101,85,.5)';
          ctx.beginPath();
          ctx.moveTo(2, h - 5);
          ctx.lineTo(end, h - 5);
          ctx.stroke();
          ctx.strokeStyle = ink(0.2);
          ctx.setLineDash([1.5, 2]);
          ctx.beginPath();
          ctx.moveTo(end, h - 5);
          ctx.lineTo(w - 2, h - 5);
          ctx.stroke();
          ctx.setLineDash([]);
          ctx.fillStyle = 'rgba(155,77,56,.72)';
          ctx.save();
          ctx.translate(end, h - 5);
          ctx.rotate(Math.PI / 4);
          ctx.fillRect(-1.5, -1.5, 3, 3);
          ctx.restore();
        } else if (kind === 'tempo') {
          const pulses = Math.round(3 + state.tempo * 1.75);
          for (let i = 0; i < pulses; i++) {
            const x = 2 + (i / Math.max(1, pulses - 1)) * (w - 4);
            const tall = i % 3 === 0 ? h * 0.58 : h * 0.32;
            ctx.strokeStyle = i % 3 === 0 ? 'rgba(95,101,85,.55)' : ink(0.26);
            ctx.lineWidth = i % 3 === 0 ? 0.85 : 0.55;
            ctx.beginPath();
            ctx.moveTo(x, mid - tall / 2);
            ctx.lineTo(x, mid + tall / 2);
            ctx.stroke();
          }
        } else if (kind === 'event') {
          const event = state.events[key];
          const color = CATASTROPHE_META[key].color;
          const steps = 60;
          for (let gen = event.interval; gen <= steps; gen += event.interval) {
            const x = 2 + (gen / steps) * (w - 4);
            ctx.strokeStyle = event.enabled ? color : ink(0.18);
            ctx.globalAlpha = event.enabled ? (gen <= state.horizon ? 0.85 : 0.28) : 0.7;
            ctx.lineWidth = 0.7;
            ctx.beginPath();
            ctx.moveTo(x, 3);
            ctx.lineTo(x, h - 3);
            ctx.stroke();
            ctx.fillStyle = ctx.strokeStyle;
            ctx.save();
            ctx.translate(x, 2.7);
            ctx.rotate(Math.PI / 4);
            ctx.fillRect(-1.2, -1.2, 2.4, 2.4);
            ctx.restore();
          }
          ctx.globalAlpha = 1;
        }
      }

      function setupTooltips() {
        document.addEventListener('pointerover', (event) => {
          const target = event.target.closest?.('[data-tip]');
          if (!target) return;
          if (target.contains(event.relatedTarget)) return;
          queueTip(target, false);
        });
        document.addEventListener('pointerout', (event) => {
          const target = event.target.closest?.('[data-tip]');
          if (!target) return;
          if (target.contains(event.relatedTarget)) return;
          hideTip();
        });
        document.addEventListener('focusin', (event) => {
          const target = event.target.closest?.('[data-tip]');
          if (target) queueTip(target, true);
        });
        document.addEventListener('focusout', (event) => {
          const next = event.relatedTarget;
          if (!next || !next.closest?.('[data-tip]')) hideTip();
        });
      }

      function queueTip(target, immediate) {
        clearTimeout(tipTimer);
        const show = () => showTip(target);
        if (immediate) show();
        else tipTimer = window.setTimeout(show, 260);
      }

      function showTip(target) {
        if (!target?.dataset.tip) return;
        tipTarget = target;
        el.toolTip.textContent = target.dataset.tip;
        el.toolTip.classList.add('is-visible');
        el.toolTip.setAttribute('aria-hidden', 'false');
        const rect = target.getBoundingClientRect();
        const tipRect = el.toolTip.getBoundingClientRect();
        let left = clamp(rect.left + rect.width / 2 - tipRect.width / 2, 10, window.innerWidth - tipRect.width - 10);
        let top = rect.top - tipRect.height - 9;
        if (top < 8) top = rect.bottom + 9;
        el.toolTip.style.left = `${left}px`;
        el.toolTip.style.top = `${top}px`;
      }

      function hideTip() {
        clearTimeout(tipTimer);
        tipTarget = null;
        el.toolTip?.classList.remove('is-visible');
        el.toolTip?.setAttribute('aria-hidden', 'true');
      }

      /* The report is completed in the next section. These are called by the
         interface above as soon as a run closes. */
      function openReport() {
        if (!sim || !sim.finished) return;
        state.reportOpen = true;
        state.running = false;
        clearTimeout(finishTimer);
        hideBanner(true);
        hideTip();
        document.body.style.overflow = 'hidden';
        el.openReportButton.hidden = true;
        el.appShell.inert = true;
        el.report.setAttribute('aria-hidden', 'false');
        el.report.classList.add('is-open');
        populateReport();
        requestAnimationFrame(() => {
          requestAnimationFrame(() => drawCharts());
        });
        window.setTimeout(() => el.reportTitle.focus({ preventScroll: true }), reducedMotion ? 0 : 480);
      }

      function closeReport(restoreFocus = true) {
        if (!state.reportOpen) return;
        state.reportOpen = false;
        el.report.classList.remove('is-open');
        el.report.setAttribute('aria-hidden', 'true');
        el.appShell.inert = false;
        document.body.style.overflow = '';
        el.openReportButton.hidden = !sim.finished;
        chartHoverIndex = null;
        chartMetrics = null;
        if (restoreFocus) el.seedInput.focus({ preventScroll: true });
      }

      function populateReport() {
        const history = sim.history;
        const first = history[0];
        const last = history[history.length - 1];
        const events = sim.catastrophes;
        const totalDeaths = sim.deaths.prey + sim.deaths.predator;
        const totalBirths = sim.births.prey + sim.births.predator;
        const finalMoss = Math.round((last?.plantCover || 0) * 100);
        const alivePrey = sim.prey.length;
        const alivePred = sim.predators.length;

        el.reportTitle.innerHTML = 'The glass <em>closed.</em>';
        el.reportNarrative.textContent = buildNarrative(first, last, events);
        el.stampGen.textContent = `GEN ${pad(sim.generation)}`;
        el.stampSeed.textContent = `Seed ${N.formatSeed(state.seed)}`;
        el.metaSeed.textContent = N.formatSeed(state.seed);
        el.metaConditions.textContent = `μ ${state.mutation.toFixed(1)}% · growth ${state.regrowth.toFixed(2)}×`;
        el.metaHorizon.textContent = `${sim.generation} / ${sim.settings.horizon} generations · ${formatter.format(sim.tick)} cycles`;
        el.metaDisturbances.textContent = `${events.length} observed`;
        el.metaFinal.textContent = `${alivePrey} glasswings · ${alivePred} embers · ${finalMoss}% moss`;
        el.statPrey.innerHTML = `${formatter.format(alivePrey)} <small>grazers</small>`;
        el.statPred.innerHTML = `${formatter.format(alivePred)} <small>hunters</small>`;
        el.statMoss.innerHTML = `${finalMoss} <small>% cover</small>`;
        el.statEvents.innerHTML = `${formatter.format(events.length)} <small>weathers</small>`;
        el.ledgerFoot.textContent = `${formatter.format(totalBirths)} births · ${formatter.format(totalDeaths)} deaths. Peaks: ${formatter.format(sim.peak.prey)} glasswings, ${formatter.format(sim.peak.predator)} embers. ${formatter.format(sim.mutations)} inherited mutations recorded.`;
        el.reportClosing.innerHTML = `<em>The plate is closed; the seed remains.</em> Every mark above was drawn from a fixed seed and a closed set of rules.`;

        el.eventLedger.replaceChildren();
        if (!events.length) {
          const empty = document.createElement('p');
          empty.className = 'event-empty';
          empty.textContent = 'No disturbance crossed the chamber. The succession was left to its own devices.';
          el.eventLedger.appendChild(empty);
        } else {
          for (const record of events) {
            const entry = document.createElement('div');
            entry.className = 'event-entry';
            entry.style.setProperty('--event-color', record.color);
            const gen = document.createElement('span');
            gen.className = 'eg';
            gen.textContent = `G${pad(record.generation)}`;
            const dot = document.createElement('i');
            dot.className = 'dot';
            const body = document.createElement('div');
            const title = document.createElement('b');
            title.textContent = record.label;
            const detail = document.createElement('span');
            detail.textContent = eventEffectCopy(record);
            body.append(title, detail);
            entry.append(gen, dot, body);
            el.eventLedger.appendChild(entry);
          }
        }
        drawCharts();
      }

      function buildNarrative(first, last, events) {
        if (!last) return 'A closed succession, drawn from a single seed.';
        const disturbanceLine = events.length
          ? `${events.length} weather${events.length === 1 ? '' : 's'} crossed the glass.`
          : 'No weather crossed the glass.';
        let ending = '';
        if (sim.prey.length === 0 && sim.predators.length === 0) {
          const preyGone = sim.extinctions.prey ? `the last glasswing vanished at generation ${sim.extinctions.prey}` : 'the glasswings were gone';
          const predGone = sim.extinctions.predator ? `the last ember at generation ${sim.extinctions.predator}` : 'the embers followed';
          ending = `Nothing with a pulse remained at the close: ${preyGone}, and ${predGone}. The moss keeps its own slow record.`;
        } else if (sim.prey.length === 0) {
          ending = `The last glasswing vanished at generation ${sim.extinctions.prey || '—'}; the embers outlived their hunger for a while, then drew the chamber closed behind them.`;
        } else if (sim.predators.length === 0) {
          ending = `The last ember spider vanished at generation ${sim.extinctions.predator || '—'}. The glasswings inherited the chamber, ${sim.prey.length} of them at the close.`;
        } else {
          ending = `At the close, ${sim.prey.length} glasswings and ${sim.predators.length} ember spiders remained. Moss held ${Math.round(last.plantCover * 100)}% of the floor.`;
        }
        const drift = traitDriftSentence(first, last);
        return `Under a fixed seed, ${sim.generation} generations passed in ${formatter.format(sim.tick)} cycles. ${disturbanceLine} ${ending}${drift ? ' ' + drift : ''}`;
      }

      function traitDriftSentence(first, last) {
        if (!first?.preyStats?.mean || !last?.preyStats?.mean) return '';
        const preyDelta = last.preyStats.mean.speed - first.preyStats.mean.speed;
        const predDelta = last.predatorStats?.mean ? last.predatorStats.mean.vision - first.predatorStats.mean.vision : 0;
        const pieces = [];
        if (Math.abs(preyDelta) >= 0.035) {
          pieces.push(`Glasswing speed ${preyDelta > 0 ? 'rose' : 'receded'} ${Math.abs(preyDelta / Math.max(0.01, first.preyStats.mean.speed) * 100).toFixed(0)}%`);
        }
        if (last.predatorStats?.mean && Math.abs(predDelta) >= 0.3) {
          pieces.push(`ember vision ${predDelta > 0 ? 'widened' : 'contracted'} ${Math.abs(predDelta / Math.max(0.01, first.predatorStats.mean.vision) * 100).toFixed(0)}%`);
        }
        if (!pieces.length) return 'The inherited means stayed close to their first morning.';
        return `In the ledger, ${pieces.join('; ')}.`;
      }

      function fmtValue(value, decimals = 2) {
        return Number(value).toFixed(decimals);
      }

      function exposeDebugApi() {
        window.__vivarium = {
          get sim() { return sim; },
          get state() { return state; },
          get view() { return view; },
          restart: (autoplay = true) => restartRun(autoplay),
          finish: () => {
            if (!sim || sim.finished) { if (sim?.finished) openReport(); return; }
            state.running = false;
            sim.hooks.onFinish = null;
            sim.runToEnd();
            scheduleCompletion();
          },
          openReport,
          closeReport,
          drawCharts,
          updateSparks,
          eventInk
        };
      }

      /* Chart implementation follows in the next script block. */
      function drawCharts() {}
      function handleChartPointerMove() {}
      function handleChartPointerLeave() {}
    })();
  </script>
</body>'''
