      };

      const el = {};
      let sim = null;
      let view = null;
      let lastFrame = 0;
      let accumulator = 0;
      let lastHudUpdate = 0;
      let finishTimer = 0;
      let tintTimer = 0;
      let bannerTimer = 0;
      let bannerBusy = false;
