        ];
        for (const id of ids) el[id] = document.getElementById(id);
        el.consoleScroll = document.querySelector('.console-scroll');
        el.eventControls = [...document.querySelectorAll('.event-control')];
        el.eventSwitches = [...document.querySelectorAll('.event-switch')];
        el.eventStepButtons = [...document.querySelectorAll('[data-event-down], [data-event-up]')];
        el.traitCanvases = {
