        const bottom = margin.t + plotH;
        const seen = new Map();
        for (const event of sim.catastrophes) {
          const x = margin.l + (clamp(event.generation, 0, horizon) / Math.max(1, horizon)) * plotW;
          ctx.save();
          ctx.strokeStyle = hexAlpha(event.color, 0.22);
          ctx.lineWidth = 0.7;
          ctx.setLineDash([1.5, 4]);
          ctx.beginPath();
          ctx.moveTo(x, top);
          ctx.lineTo(x, bottom);
          ctx.stroke();
          ctx.setLineDash([]);
          if (withLetters) {
            const lane = (seen.get(event.generation) || 0);
            seen.set(event.generation, lane + 1);
            ctx.fillStyle = hexAlpha(event.color, 0.9);
            ctx.font = '500 7px "SFMono-Regular", Menlo, Consolas, monospace';
            ctx.textAlign = 'center';
            ctx.fillText(event.glyph, x, top - 10 - lane * 9);
