      function drawPopulationChart() {
        const fit = fitChartCanvas(el.populationChart);
        if (!fit || !sim) return;
        const { ctx, w, h } = fit;
        const colors = populationColors();
        const history = sim.history;
        if (!history.length) return;

        const horizon = Math.max(1, sim.settings.horizon, history[history.length - 1].generation);
        const margin = { l: w < 480 ? 40 : 50, r: w < 480 ? 36 : 48, t: 43, b: 29 };
