        const leftMax = niceCeil(maxAnimals * 1.08);
        const rightMax = 100;
        const mapX = (generation) => margin.l + (clamp(generation, 0, horizon) / horizon) * plotW;
        const mapLeftY = (value) => margin.t + (1 - clamp(value / leftMax, 0, 1)) * plotH;
        const mapRightY = (value) => margin.t + (1 - clamp(value / rightMax, 0, 1)) * plotH;

        ctx.save();
        // Paper/chart bed, drawn almost transparently so the sheet remains visible.
        const bed = ctx.createLinearGradient(0, margin.t, 0, bottom);
        bed.addColorStop(0, 'rgba(255,250,238,.27)');
        bed.addColorStop(1, 'rgba(255,250,238,.08)');
        ctx.fillStyle = bed;
        ctx.fillRect(margin.l, margin.t, plotW, plotH);

        // Horizontal rules and left labels.
        const yTicks = 4;
        ctx.font = '7.5px "SFMono-Regular", Menlo, Consolas, monospace';
        ctx.textBaseline = 'middle';
        for (let i = 0; i <= yTicks; i++) {
          const y = margin.t + (i / yTicks) * plotH;
          ctx.strokeStyle = i === yTicks ? 'rgba(32,38,30,.28)' : 'rgba(32,38,30,.09)';
          ctx.lineWidth = i === yTicks ? 0.75 : 0.5;
          ctx.beginPath();
          ctx.moveTo(margin.l, y);
          ctx.lineTo(margin.l + plotW, y);
          ctx.stroke();
          ctx.fillStyle = colors.soft;
          ctx.textAlign = 'right';
          ctx.fillText(formatter.format(Math.round(leftMax * (1 - i / yTicks))), margin.l - 8, y);
        }

        // Right axis: living moss cover.
        ctx.textAlign = 'left';
        ctx.fillStyle = colors.moss;
        for (let i = 0; i <= 2; i++) {
          const value = 100 - i * 50;
          const y = margin.t + (i / 2) * plotH;
          ctx.globalAlpha = 0.8;
          ctx.fillText(`${value}%`, margin.l + plotW + 8, y);
        }
        ctx.globalAlpha = 1;

        // Generation labels.
        const step = generationStep(horizon);
        ctx.fillStyle = colors.soft;
        ctx.font = '7px "SFMono-Regular", Menlo, Consolas, monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        for (let g = 0; g <= horizon; g += step) {
