        ctx.font = '6.5px "SFMono-Regular", Menlo, Consolas, monospace';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'bottom';
        ctx.fillText('A N I M A L   C O U N T', margin.l, margin.t - 22);
        ctx.textAlign = 'right';
        ctx.fillStyle = 'rgba(102,119,68,.72)';
        ctx.fillText('M O S S   C O V E R', margin.l + plotW, margin.t - 22);

        // Hover crosshair.
        if (chartHoverIndex !== null && history[chartHoverIndex]) {
          const point = history[chartHoverIndex];
          const x = mapX(point.generation);
          ctx.strokeStyle = 'rgba(32,38,30,.35)';
          ctx.lineWidth = 0.7;
          ctx.setLineDash([2, 3]);
          ctx.beginPath();
          ctx.moveTo(x, margin.t);
          ctx.lineTo(x, bottom);
          ctx.stroke();
          ctx.setLineDash([]);
          for (const line of series) {
            ctx.fillStyle = line.color;
            ctx.beginPath();
            ctx.arc(x, mapLeftY(point[line.key]), 2.8, 0, TAU);
            ctx.fill();
          }
          ctx.fillStyle = colors.moss;
          ctx.beginPath();
          ctx.arc(x, mapRightY(point.plantCover * 100), 2.5, 0, TAU);
          ctx.fill();
        }

        ctx.restore();
        chartMetrics = { margin, plotW, plotH, horizon, bottom, history };
        el.populationChart.setAttribute('aria-label', `Population curves over ${horizon} generations: glasswings peak at ${formatter.format(sim.peak.prey)}, ember spiders peak at ${formatter.format(sim.peak.predator)}, moss closes at ${Math.round(history[history.length - 1].plantCover * 100)} percent cover.`);
      }

      function drawTraitChart(gene) {
        const canvas = el.traitCanvases[gene];
        const fit = fitChartCanvas(canvas);
        if (!fit || !sim) return;
        const { ctx, w, h } = fit;
        const history = sim.history;
        if (!history.length) return;
        const colors = populationColors();
        const horizon = Math.max(1, sim.settings.horizon, history[history.length - 1].generation);
        const margin = { l: 34, r: 10, t: 10, b: 18 };
        const plotW = Math.max(10, w - margin.l - margin.r);
        const plotH = Math.max(10, h - margin.t - margin.b);
        const bottom = margin.t + plotH;
        const mapX = (g) => margin.l + (clamp(g, 0, horizon) / horizon) * plotW;

        const series = [
          { key: 'preyStats', color: colors.prey, dash: [], label: 'Glasswing' },
          { key: 'predatorStats', color: colors.predator, dash: [4, 3], label: 'Ember' }
        ];
        let lo = Infinity;
        let hi = -Infinity;
        for (const point of history) {
          for (const s of series) {
            const stats = point[s.key];
            if (!stats?.mean) continue;
            const mean = stats.mean[gene];
            const sd = stats.sd[gene];
            lo = Math.min(lo, mean - sd * 1.05);
            hi = Math.max(hi, mean + sd * 1.05);
          }
        }
        if (!Number.isFinite(lo) || !Number.isFinite(hi)) {
          ctx.fillStyle = 'rgba(95,101,85,.7)';
          ctx.font = 'italic 11px "Iowan Old Style", Palatino, Georgia, serif';
          ctx.textAlign = 'center';
          ctx.fillText('No observations remained.', w / 2, h / 2);
