        const pad = Math.max((hi - lo) * 0.18, gene === 'repro' ? 2 : 0.02);
        lo -= pad;
        hi += pad;
        const mapY = (value) => margin.t + (1 - (value - lo) / (hi - lo)) * plotH;
        const decimals = gene === 'speed' ? 2 : gene === 'vision' ? 1 : gene === 'metabolism' ? 2 : 0;

        ctx.save();
        ctx.fillStyle = 'rgba(255,250,238,.17)';
        ctx.fillRect(margin.l, margin.t, plotW, plotH);

        ctx.font = '6.8px "SFMono-Regular", Menlo, Consolas, monospace';
        ctx.textBaseline = 'middle';
        for (let i = 0; i <= 2; i++) {
          const value = hi - (i / 2) * (hi - lo);
          const y = margin.t + (i / 2) * plotH;
          ctx.strokeStyle = i === 2 ? 'rgba(32,38,30,.25)' : 'rgba(32,38,30,.08)';
          ctx.lineWidth = 0.55;
          ctx.beginPath();
          ctx.moveTo(margin.l, y);
          ctx.lineTo(margin.l + plotW, y);
          ctx.stroke();
          ctx.fillStyle = 'rgba(95,101,85,.74)';
          ctx.textAlign = 'right';
          ctx.fillText(value.toFixed(decimals), margin.l - 6, y);
        }

