              const y = mapY(point.mean + point.sd);
              if (index === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            });
            for (let i = segment.length - 1; i >= 0; i--) {
              const point = segment[i];
              ctx.lineTo(mapX(point.generation), mapY(point.mean - point.sd));
            }
            ctx.closePath();
            ctx.fillStyle = s.color === colors.prey ? 'rgba(155,114,46,.09)' : 'rgba(155,77,56,.08)';
            ctx.fill();
          }
        }

        // Then the mean line.
        for (const s of series) {
          const segments = [];
          let current = [];
          history.forEach((point) => {
            const stats = point[s.key];
            if (stats?.mean) current.push({ generation: point.generation, value: stats.mean[gene] });
            else if (current.length) { segments.push(current); current = []; }
          });
          if (current.length) segments.push(current);
          for (const segment of segments) {
            ctx.beginPath();
            segment.forEach((point, index) => {
              const x = mapX(point.generation);
              const y = mapY(point.value);
              if (index === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            });
            ctx.strokeStyle = s.color;
            ctx.lineWidth = 1.25;
            ctx.setLineDash(s.dash);
            ctx.lineJoin = 'round';
            ctx.stroke();
            ctx.setLineDash([]);
            if (segment.length) {
              const last = segment[segment.length - 1];
              ctx.fillStyle = s.color;
              ctx.beginPath();
              ctx.arc(mapX(last.generation), mapY(last.value), 1.45, 0, TAU);
              ctx.fill();
            }
          }
        }

        // The horizon ticks, extremely quiet.
        ctx.font = '6.5px "SFMono-Regular", Menlo, Consolas, monospace';
        ctx.fillStyle = 'rgba(95,101,85,.6)';
        ctx.textBaseline = 'top';
        ctx.textAlign = 'left';
        ctx.fillText('0', margin.l, bottom + 6);
        ctx.textAlign = 'right';
        ctx.fillText(`${horizon} gen`, margin.l + plotW, bottom + 6);
        ctx.restore();
      }

      function handleChartPointerMove(event) {
        if (!sim || !state.reportOpen || !chartMetrics) return;
        const canvas = el.populationChart;
        const rect = canvas.getBoundingClientRect();
        const x = event.clientX - rect.left;
        const y = event.clientY - rect.top;
        const { margin, plotW, horizon } = chartMetrics;
        if (x < margin.l - 4 || x > margin.l + plotW + 4) {
          handleChartPointerLeave();
          return;
        }
        const generation = clamp(Math.round((x - margin.l) / plotW * horizon), 0, horizon);
        const history = chartMetrics.history;
        let nearest = 0;
        let best = Infinity;
        history.forEach((point, index) => {
          const distance = Math.abs(point.generation - generation);
          if (distance < best) { best = distance; nearest = index; }
        });
        if (chartHoverIndex === nearest && el.chartTip.classList.contains('is-visible')) return;
        chartHoverIndex = nearest;
        drawPopulationChart();
        populateChartTip(history[nearest], x, y, rect, canvas.parentElement);
      }

      function populateChartTip(point, x, y, canvasRect, wrap) {
        if (!point) return;
        el.chartTip.replaceChildren();
        const heading = document.createElement('strong');
        heading.textContent = `Generation ${pad(point.generation)}`;
        const rows = [
          ['Moss cover', `${Math.round(point.plantCover * 100)}%`],
          ['Glasswings', formatter.format(point.prey)],
          ['Ember spiders', formatter.format(point.predator)]
        ];
        el.chartTip.appendChild(heading);
        for (const [label, value] of rows) {
          const row = document.createElement('div');
          row.className = 'tip-row';
          const name = document.createElement('span');
          name.textContent = label;
          const val = document.createElement('span');
          val.textContent = value;
          row.append(name, val);
          el.chartTip.appendChild(row);
        }
        if (point.events?.length) {
          const eventLine = document.createElement('div');
          eventLine.className = 'tip-event';
          eventLine.textContent = point.events.map(e => `${e.label} crossed the glass`).join(' · ');
          el.chartTip.appendChild(eventLine);
        }
        el.chartTip.classList.add('is-visible');
        el.chartTip.setAttribute('aria-hidden', 'false');
        const wrapRect = wrap.getBoundingClientRect();
        const tipRect = el.chartTip.getBoundingClientRect();
        const localX = canvasRect.left - wrapRect.left + x;
        const localY = canvasRect.top - wrapRect.top + y;
        let left = localX + 14;
        if (left + tipRect.width > wrapRect.width - 6) left = localX - tipRect.width - 14;
        left = clamp(left, 4, wrapRect.width - tipRect.width - 4);
        let top = localY - tipRect.height - 10;
        if (top < 4) top = localY + 12;
        top = clamp(top, 4, wrapRect.height - tipRect.height - 4);
        el.chartTip.style.left = `${left}px`;
        el.chartTip.style.top = `${top}px`;
      }

      function handleChartPointerLeave() {
        if (!state.reportOpen) return;
        chartHoverIndex = null;
        el.chartTip.classList.remove('is-visible');
        el.chartTip.setAttribute('aria-hidden', 'true');
        drawPopulationChart();
      }
    })();
  </script>
</body>'''
