const fs=require('fs');
(async()=>{
 const targets=await (await fetch('http://127.0.0.1/json')).json();
 const page=targets.find(t=>t.type==='page' && t.url.startsWith('file:'));
 const ws=new WebSocket(page.webSocketDebuggerUrl);
 let id=0; const pending=new Map(); const logs=[];
 const send=(m,p={})=>new Promise((res,rej)=>{const i=++id;pending.set(i,{res,rej});ws.send(JSON.stringify({id:i,method:m,params:p}))});
 ws.onmessage=ev=>{const msg=JSON.parse(ev.data);if(msg.id&&pending.has(msg.id)){const {res,rej}=pending.get(msg.id);pending.delete(msg.id);msg.error?rej(msg.error):res(msg.result)} else if(msg.method==='Runtime.exceptionThrown'){logs.push(['exception',msg.params.exceptionDetails.exception?.description||msg.params.exceptionDetails.text])} else if(msg.method==='Runtime.consoleAPICalled'){logs.push(['console',...msg.params.args.map(a=>a.value??a.description)])}};
 await new Promise(r=>ws.onopen=r);
 await send('Runtime.enable');
 await send('Page.navigate',{url:'file://<WS3>/index.html'});
 await new Promise(r=>setTimeout(r,2500));
 let r=await send('Runtime.evaluate',{expression:`({tick:__vivarium.sim.tick,prey:__vivarium.sim.prey.length,pred:__vivarium.sim.predators.length,history:__vivarium.sim.history.length})`,returnByValue:true});
 console.log('loaded',r.result.value);
 // set horizon to 8 for a short run, or fast forward current
 r=await send('Runtime.evaluate',{expression:`__vivarium.finish(); 'finishing'`,returnByValue:true, awaitPromise:false});
 console.log(r.result.value,logs);
 await new Promise(r=>setTimeout(r,2600));
 r=await send('Runtime.evaluate',{expression:`({finish:__vivarium.sim.finished, gen:__vivarium.sim.generation, report:document.getElementById('report').classList.contains('is-open'), charts:[document.getElementById('populationChart').width,document.getElementById('populationChart').height], err:window.__err})`,returnByValue:true});
 console.log('end state',r.result.value);
 let shot=await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});
 fs.writeFileSync('<TMP>/viv-report.png',Buffer.from(shot.data,'base64'));
 console.log('logs',JSON.stringify(logs,null,2));
 // full page screenshot too
 shot=await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:true});
 fs.writeFileSync('<TMP>/viv-report-full.png',Buffer.from(shot.data,'base64'));
 ws.close();
})();
