const fs=require('fs'),vm=require('vm');
const html=fs.readFileSync('index.html','utf8');
const m=html.match(/<script>\s*\/\* =+\n\s*I\. THE ENGINE[\s\S]*?<\/script>/);
const code=m[0].replace(/^<script>/,'').replace(/<\/script>$/,'');
const sandbox={window:{},console,Math};vm.createContext(sandbox);vm.runInContext(code,sandbox);
const {VivariumEngine}=sandbox.window.Nocturne;
for(const regrowth of [1.1,1.3,1.5]){
 for(const seed of [101,2,17,42]){
   const e=new VivariumEngine({seed,regrowth,horizon:36}); e.runToEnd();
   const hs=e.history; const last=hs.at(-1);
   const minMoss=Math.min(...hs.map(h=>Math.round(h.plantCover*100)));
   console.log(`r${regrowth} s${seed} end prey ${String(e.prey.length).padStart(3)} pred ${String(e.predators.length).padStart(2)} moss ${String(Math.round(last.plantCover*100)).padStart(2)}% minMoss ${minMoss}% peakPrey ${Math.max(...hs.map(h=>h.prey))}`);
 }
}
