{"command":"node - <<'NODE'
const fs=require('fs');
(async()=>{
 const targets=await (await fetch('http://127.0.0.1/json')).json();
 const page=targets.find(t=>t.type==='page' && t.url.startsWith('file:'));
 const ws=new WebSocket(page.webSocketDebuggerUrl);
 let id=0; const pending=new Map(); const logs=[];
 const send=(m,p={})=>new Promise((res,rej)=>{const i=++id;pending.set(i,{res,rej});ws.send(JSON.stringify({id:i,method:m,params:p}))});
 ws.onmessage=ev=>{const msg=JSON.parse(ev.data);if(msg.id&&pending.has(msg.id)){const {res,rej}=pending.get(msg.id);pending.delete(msg.id);msg.error?rej(msg.error):res(msg.result)} else if(msg.method==='Runtime.exceptionThrown'){logs.push(['exception',msg.params.exceptionDetails.exception?.description||msg.params.exceptionDetails.text])}};
 await new Promise(r=>ws.onopen=r);
 await send('Runtime.enable');
 await send('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:1,mobile:false});
 await send('Page.navigate',{url:'file://<WS3>/index.html'});
 await new Promise(r=>setTimeout(r,3600));
 let shot=await send('Page.captureScreenshot',{format:'png'});
 fs.writeFileSync('<TMP>/viv3.png',Buffer.from(shot.data,'base64'));
 let r=await send('Runtime.evaluate',{expression:`({tick:__vivarium.sim.tick, gen:__vivarium.sim.generation, prey:__vivarium.sim.prey.length,pred:__vivarium.sim.predators.length,cover:__vivarium.sim.summaryStats().cover, exceptions: []})`,returnByValue:true});
 console.log('state',r.result.value);
 await send('Runtime.evaluate',{expression:`__vivarium.finish(); true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,1800));
 shot=await send('Page.captureScreenshot',{format:'png'});
 fs.writeFileSync('<TMP>/viv-report2.png',Buffer.from(shot.data,'base64'));
 // scroll report to traits
 await send('Runtime.evaluate',{expression:`document.getElementById('report').scrollTop = document.querySelector('.traits-figure').offsetTop - 80; document.getElementById('report').scrollTop`,returnByValue:true});
 await new Promise(r=>setTimeout(r,400));
 shot=await send('Page.captureScreenshot',{format:'png'});
 fs.writeFileSync('<TMP>/viv-report-traits.png',Buffer.from(shot.data,'base64'));
 console.log('logs',JSON.stringify(logs,null,2));
 ws.close();
})();
