const fs=require('fs');
(async()=>{
 const targets=await (await fetch('http://127.0.0.1/json')).json();
 const page=targets.find(t=>t.type==='page' && t.url.startsWith('file:'));
 const ws=new WebSocket(page.webSocketDebuggerUrl);
 let id=0; const pending=new Map(); const errors=[];
 const send=(m,p={})=>new Promise((r,j)=>{const i=++id;pending.set(i,{r,j});ws.send(JSON.stringify({id:i,method:m,params:p}))});
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.j(m.error):p.r(m.result)} else if(m.method==='Runtime.exceptionThrown'){errors.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text)}};
 await new Promise(r=>ws.onopen=r);
 await send('Runtime.enable');
 await send('Page.reload',{ignoreCache:true});
 await new Promise(r=>setTimeout(r,1500));
 errors.length=0;
 let r=await send('Runtime.evaluate',{expression:`(()=>{ __vivarium.state.running=false; const target=9*180; while(__vivarium.sim.tick<target) __vivarium.sim.step(); return {tick:__vivarium.sim.tick,gen:__vivarium.sim.generation,events:__vivarium.sim.catastrophes.length, banner:document.getElementById('eventBanner').classList.contains('is-visible')}; })()`,returnByValue:true});
 console.log('stepped',r.result.value);
 await new Promise(r=>setTimeout(r,500));
 let shot=await send('Page.captureScreenshot',{format:'png'});
 fs.writeFileSync('<TMP>/viv-event.png',Buffer.from(shot.data,'base64'));
 r=await send('Runtime.evaluate',{expression:`({banner:document.getElementById('eventBanner').className, kind:document.getElementById('eventKind').textContent, count:document.getElementById('preyCount').textContent, condition:document.getElementById('conditionText').textContent})`,returnByValue:true});
 console.log(r.result.value);
 console.log('errors',errors);
 ws.close();
})();
