const fs=require('fs');
(async()=>{
 const targets=await (await fetch('http://127.0.0.1/json')).json();
 const page=targets.find(t=>t.type==='page' && t.url.startsWith('file:'));
 const ws=new WebSocket(page.webSocketDebuggerUrl);
 let id=0;const pending=new Map();const errors=[];
 const send=(m,p={})=>new Promise((r,j)=>{const i=++id;pending.set(i,{r,j});ws.send(JSON.stringify({id:i,method:m,params:p}))});
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.j(m.error):p.r(m.result)}else if(m.method==='Runtime.exceptionThrown'){errors.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text)}};
 await new Promise(r=>ws.onopen=r);
 await send('Runtime.enable');
 await send('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:1,mobile:false,screenWidth:1440,screenHeight:900});
 await send('Page.reload',{ignoreCache:true});
 await new Promise(r=>setTimeout(r,2000));
 errors.length=0;
 let r=await send('Runtime.evaluate',{expression:`(()=>{const q=s=>{const e=document.querySelector(s);if(!e)return null;const r=e.getBoundingClientRect();return {top:+r.top.toFixed(1),h:+r.height.toFixed(1),bottom:+r.bottom.toFixed(1)}};return {inner:[innerWidth,innerHeight],docH:document.documentElement.scrollHeight,head:q('.masthead'),main:q('.workbench'),stage:q('.stage-shell'),console:q('.console'),consoleScroll:q('.console-scroll'),footnote:q('.plate-footnote'),folio:q('.folio'),tick:__vivarium.sim.tick,seed:__vivarium.state.seed}})()`,returnByValue:true});
 console.log('layout',JSON.stringify(r.result.value,null,2));
 let shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/viv6.png',Buffer.from(shot.data,'base64'));
 // interaction checks
 r=await send('Runtime.evaluate',{expression:`(()=>{
  const mr=document.getElementById('mutationRange'); mr.value='20'; mr.dispatchEvent(new Event('input',{bubbles:true}));
  const rr=document.getElementById('regrowthRange'); rr.value='185'; rr.dispatchEvent(new Event('input',{bubbles:true}));
  document.getElementById('horizonUp').click();
  document.querySelector('.event-switch[data-kind="drought"]').click();
  document.getElementById('tempoDial').focus(); document.getElementById('tempoDial').dispatchEvent(new KeyboardEvent('keydown',{key:'End',bubbles:true}));
  const si=document.getElementById('seedInput'); si.value='000202'; si.dispatchEvent(new Event('change',{bubbles:true}));
  return {mutation:__vivarium.sim.settings.mutation, mutationText:document.getElementById('mutationValue').textContent.trim(), regrowth:__vivarium.sim.settings.regrowth, horizon:__vivarium.state.horizon, drought:__vivarium.sim.eventSettings.drought.enabled, droughtSwitch:document.querySelector('.event-switch[data-kind="drought"]').getAttribute('aria-checked'), tempo:__vivarium.state.tempo, tempoLabel:document.getElementById('tempoValue').textContent.trim(), seed:__vivarium.sim.seed, seedField:document.getElementById('seedInput').value, tick:__vivarium.sim.tick, focus:document.activeElement.id, ariaDesc:document.getElementById('mutationRange').getAttribute('aria-describedby')};
 })()`,returnByValue:true});
 console.log('interactions',JSON.stringify(r.result.value,null,2));
 await new Promise(r=>setTimeout(r,1000));
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/viv6-controls.png',Buffer.from(shot.data,'base64'));
 console.log('errors',errors);
 ws.close();
})();
