 await new Promise(r=>ws.onopen=r);
 await send('Runtime.enable');
 await send('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:1,mobile:false,screenWidth:1440,screenHeight:900});
 let r=await send('Runtime.evaluate',{expression:`({finished:__vivarium.sim.finished, reportOpen:__vivarium.state.reportOpen, gen:__vivarium.sim.generation, run:__vivarium.state.running, reportH:document.getElementById('report').scrollHeight, inner:[innerWidth,innerHeight]})`,returnByValue:true});
 console.log('state',r.result.value);
