 const pt=r.result.value;
 await send('Input.dispatchMouseEvent',{type:'mouseMoved',x:pt.x,y:pt.y});
 await new Promise(r=>setTimeout(r,250));
 r=await send('Runtime.evaluate',{expression:`({tip:document.getElementById('chartTip').className,text:document.getElementById('chartTip').textContent.trim(), tipRect:(()=>{const t=document.getElementById('chartTip').getBoundingClientRect();return {x:t.x,y:t.y,w:t.width,h:t.height}})(), scrollTop:document.getElementById('report').scrollTop})`,returnByValue:true});
 console.log('hover',r.result.value);
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/viv-report-hover.png',Buffer.from(shot.data,'base64'));
 // scroll to trait charts
 await send('Runtime.evaluate',{expression:`document.getElementById('report').scrollTop = document.querySelector('.traits-figure').offsetTop - 40; true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,300));
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/viv-report-traits2.png',Buffer.from(shot.data,'base64'));
 console.log('errors',errors);
 ws.close();
})();
