{"command":"node - <<'NODE'
const fs=require('fs');
(async()=>{
 const targets=await (await fetch('http://127.0.0.1/json')).json();
 const page=targets.find(t=>t.type==='page' && t.url.startsWith('file:'));
 const ws=new WebSocket(page.webSocketDebuggerUrl);
 let id=0;const pending=new Map();const errors=[];
 const send=(m,p={})=>new Promise((r,j)=>{const i=++id;pending.set(i,{r,j});ws.send(JSON.stringify({id:i,method:m,params:p}))});
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.j(m.error):p.r(m.result)}else if(m.method==='Runtime.exceptionThrown'){errors.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text)}};
 await new Promise(r=>ws.onopen=r);
 await send('Runtime.enable');
 await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:2,mobile:true,screenWidth:390,screenHeight:844});
 await send('Page.reload',{ignoreCache:true});
 await new Promise(r=>setTimeout(r,1800));
 errors.length=0;
 let r=await send('Runtime.evaluate',{expression:`(()=>({inner:[innerWidth,innerHeight],docH:document.documentElement.scrollHeight,docW:document.documentElement.scrollWidth,bodyW:document.body.scrollWidth,stage:[document.getElementById('world').clientWidth,document.getElementById('world').clientHeight],consoleTop:Math.round(document.querySelector('.console').getBoundingClientRect().top),errorsInDom:!!document.querySelector('.error')}))()`,returnByValue:true});
 console.log(JSON.stringify(r.result.value,null,2));
 let shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/viv-mobile.png',Buffer.from(shot.data,'base64'));
 // scroll to console
 await send('Runtime.evaluate',{expression:`window.scrollTo(0, document.querySelector('.console').getBoundingClientRect().top + window.scrollY - 8); true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,250));
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/viv-mobile-console.png',Buffer.from(shot.data,'base64'));
 // finish and report mobile
 await send('Runtime.evaluate',{expression:`__vivarium.finish(); true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,1800));
 await send('Runtime.evaluate',{expression:`window.scrollTo(0,0); true`,returnByValue:true});
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/viv-mobile-report.png',Buffer.from(shot.data,'base64'));
 console.log('errors',errors);
 ws.close();
})();
