old="""          // Tiny coordinate notations at the margins.
          ctx.fillStyle = 'rgba(221,211,184,.26)';
          ctx.font = '7px \"SFMono-Regular\", Menlo, Consolas, monospace';
          ctx.textAlign = 'left';
          ctx.fillText('00', 18, h - 17);
          ctx.textAlign = 'right';
          ctx.fillText('168 × 104', w - 18, h - 17);
          ctx.restore();"""
new="""          // The observatory's pressed seal, ghosted onto the reverse of the glass.
          ctx.save();
          ctx.translate(w * 0.52, h * 0.47);
          ctx.rotate(-0.22);
          const sealR = Math.min(w, h) * 0.105;
          ctx.strokeStyle = 'rgba(210,198,167,.075)';
          ctx.lineWidth = 0.55;
          ctx.beginPath();
          ctx.arc(0, 0, sealR * 0.31, 0, TAU);
          ctx.stroke();
          for (let petal = 0; petal < 8; petal++) {
            const angle = petal * TAU / 8;
            const tipX = Math.cos(angle) * sealR;
            const tipY = Math.sin(angle) * sealR;
            const leftX = Math.cos(angle - 0.42) * sealR * 0.58;
            const leftY = Math.sin(angle - 0.42) * sealR * 0.58;
            const rightX = Math.cos(angle + 0.42) * sealR * 0.58;
            const rightY = Math.sin(angle + 0.42) * sealR * 0.58;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.quadraticCurveTo(leftX, leftY, tipX, tipY);
            ctx.quadraticCurveTo(rightX, rightY, 0, 0);
            ctx.stroke();
          }
          ctx.fillStyle = 'rgba(210,198,167,.13)';
          ctx.beginPath();
          ctx.arc(0, 0, 1.1, 0, TAU);
          ctx.fill();
          ctx.restore();

          // Tiny coordinate notations at the margins.
          ctx.fillStyle = 'rgba(221,211,184,.26)';
          ctx.font = '7px \"SFMono-Regular\", Menlo, Consolas, monospace';
          ctx.textAlign = 'left';
          ctx.fillText('00', 18, h - 17);
          ctx.textAlign = 'right';
          ctx.fillText('168 × 104', w - 18, h - 17);
          ctx.restore();"""
if old not in s: raise SystemExit('signature slot not found')
s=s.replace(old,new)
p.write_text(s)
