{"command":"node - <<'NODE'
const fs=require('fs');
(async()=>{
 const targets=await (await fetch('http://127.0.0.1/json')).json();
 const page=targets.find(t=>t.type==='page' && t.url.startsWith('file:'));
 const ws=new WebSocket(page.webSocketDebuggerUrl);
 let id=0;const pending=new Map();const errors=[];
 const send=(m,p={})=>new Promise((r,j)=>{const i=++id;pending.set(i,{r,j});ws.send(JSON.stringify({id:i,method:m,params:p}))});
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.j(m.error):p.r(m.result)}else if(m.method==='Runtime.exceptionThrown'){errors.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text)}};
 await new Promise(r=>ws.onopen=r);
 await send('Runtime.enable');
 await send('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:1,mobile:false,screenWidth:1440,screenHeight:900});
 await send('Page.reload',{ignoreCache:true});
 await new Promise(r=>setTimeout(r,2200));
 errors.length=0;
 let r=await send('Runtime.evaluate',{expression:`(()=>({seed:__vivarium.sim.seed,tick:__vivarium.sim.tick,gen:__vivarium.sim.generation,inner:[innerWidth,innerHeight],docH:document.documentElement.scrollHeight,consoleScroll:[document.querySelector('.console-scroll').clientHeight,document.querySelector('.console-scroll').scrollHeight],resources:performance.getEntriesByType('resource').map(x=>x.name),reportOpen:__vivarium.state.reportOpen, hint:document.querySelector('.dial-scale').textContent}))()`,returnByValue:true});
 console.log('initial',JSON.stringify(r.result.value,null,2));
 let shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final-stage.png',Buffer.from(shot.data,'base64'));
 // test focus trap and close/reopen via UI
 await send('Runtime.evaluate',{expression:`__vivarium.finish(); true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,1800));
 console.log('report state',(await send('Runtime.evaluate',{expression:`({open:__vivarium.state.reportOpen,prey:__vivarium.sim.prey.length,pred:__vivarium.sim.predators.length,gen:__vivarium.sim.generation,events:__vivarium.sim.catastrophes.length})`,returnByValue:true})).result.value);
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final-report.png',Buffer.from(shot.data,'base64'));
 // hover chart
 r=await send('Runtime.evaluate',{expression:`(()=>{const c=document.getElementById('populationChart');const r=c.getBoundingClientRect();return {x:r.left+r.width*0.53,y:r.top+r.height*0.4};})()`,returnByValue:true});
 await send('Input.dispatchMouseEvent',{type:'mouseMoved',x:r.result.value.x,y:r.result.value.y});
 await new Promise(r=>setTimeout(r,180));
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final-report-hover.png',Buffer.from(shot.data,'base64'));
 // scroll traits
 await send('Runtime.evaluate',{expression:`document.getElementById('report').scrollTop = document.querySelector('.traits-figure').offsetTop - 34; true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,250));
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final-traits.png',Buffer.from(shot.data,'base64'));
 // test close via inspect
 await send('Runtime.evaluate',{expression:`document.getElementById('inspectButton').click(); true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,700));
 r=await send('Runtime.evaluate',{expression:`({open:__vivarium.state.reportOpen,focus:document.activeElement.id,appInert:document.getElementById('appShell').inert,reopenHidden:document.getElementById('openReportButton').hidden})`,returnByValue:true});
 console.log('close result',r.result.value);
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final-inspect.png',Buffer.from(shot.data,'base64'));
 // reopen via button
 await send('Runtime.evaluate',{expression:`document.getElementById('openReportButton').click(); true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,600));
 r=await send('Runtime.evaluate',{expression:`({open:__vivarium.state.reportOpen,focus:document.activeElement.id||document.activeElement.className, chartTip:document.getElementById('chartTip').className})`,returnByValue:true});
 console.log('reopen result',r.result.value);
 console.log('errors',errors);
 ws.close();
})();
