# event list height
s=s.replace(".event-ledger-list { max-height: 274px;", ".event-ledger-list { max-height: 324px;")
# chart note
s=s.replace('<span>Moss cover / right axis · animal counts / left axis</span>', '<span>Moss cover / right axis · counts / left axis (log)</span>')
# log scale mapping
s=s.replace("""        const maxAnimals = Math.max(20, ...history.map(d => Math.max(d.prey, d.predator)));
        const leftMax = niceCeil(maxAnimals * 1.08);
        const rightMax = 100;
        const mapX = (generation) => margin.l + (clamp(generation, 0, horizon) / horizon) * plotW;
        const mapLeftY = (value) => margin.t + (1 - clamp(value / leftMax, 0, 1)) * plotH;
        const mapRightY = (value) => margin.t + (1 - clamp(value / rightMax, 0, 1)) * plotH;""","""        const maxAnimals = Math.max(20, ...history.map(d => Math.max(d.prey, d.predator)));
        const leftMax = niceCeil(maxAnimals * 1.08);
        const logMax = Math.log10(leftMax + 1);
        const rightMax = 100;
        const mapX = (generation) => margin.l + (clamp(generation, 0, horizon) / horizon) * plotW;
        // Counts use a logarithmic left axis: 20 embers should not vanish
        // against a bloom of 700 glasswings.
        const mapLeftY = (value) => margin.t + (1 - Math.log10(clamp(value, 0, leftMax) + 1) / logMax) * plotH;
        const mapRightY = (value) => margin.t + (1 - clamp(value / rightMax, 0, 1)) * plotH;""")
s=s.replace("""        // Horizontal rules and left labels.
        const yTicks = 4;
        ctx.font = `${axisFont}px \"SFMono-Regular\", Menlo, Consolas, monospace`;
        ctx.textBaseline = 'middle';
        for (let i = 0; i <= yTicks; i++) {
          const y = margin.t + (i / yTicks) * plotH;
          ctx.strokeStyle = i === yTicks ? 'rgba(32,38,30,.28)' : 'rgba(32,38,30,.09)';
          ctx.lineWidth = i === yTicks ? 0.75 : 0.5;
          ctx.beginPath();
          ctx.moveTo(margin.l, y);
          ctx.lineTo(margin.l + plotW, y);
          ctx.stroke();
          ctx.fillStyle = colors.soft;
          ctx.textAlign = 'right';
          ctx.fillText(formatter.format(Math.round(leftMax * (1 - i / yTicks))), margin.l - 8, y);
        }""","""        // Horizontal rules and log-scale count labels.
        const countTicks = [0, 10, 100, 1000, 10000].filter(v => v <= leftMax);
        if (countTicks[countTicks.length - 1] !== leftMax) countTicks.push(leftMax);
        ctx.font = `${axisFont}px \"SFMono-Regular\", Menlo, Consolas, monospace`;
        ctx.textBaseline = 'middle';
        for (const tick of countTicks) {
          const y = mapLeftY(tick);
          const baseline = tick === 0;
          ctx.strokeStyle = baseline ? 'rgba(32,38,30,.28)' : 'rgba(32,38,30,.09)';
          ctx.lineWidth = baseline ? 0.75 : 0.5;
          ctx.beginPath();
          ctx.moveTo(margin.l, y);
          ctx.lineTo(margin.l + plotW, y);
          ctx.stroke();
          ctx.fillStyle = colors.soft;
          ctx.textAlign = 'right';
          ctx.fillText(formatter.format(tick), margin.l - 8, y);
        }""")
s=s.replace("        ctx.fillText('A N I M A L   C O U N T', margin.l, margin.t - 22);", "        ctx.fillText('A N I M A L   C O U N T   ·   L O G', margin.l, margin.t - 22);")
s=s.replace("        ctx.fillText('M O S S   C O V E R', margin.l + plotW, margin.t - 22);", "        ctx.fillText('M O S S   C O V E R', margin.l + plotW, margin.t - 22);")
p.write_text(s)
