const fs=require('fs');
(async()=>{
 const targets=await (await fetch('http://127.0.0.1/json')).json();
 const page=targets.find(t=>t.type==='page' && t.url.startsWith('file:'));
 const ws=new WebSocket(page.webSocketDebuggerUrl);
 let id=0;const pending=new Map();const errors=[];
 const send=(m,p={})=>new Promise((r,j)=>{const i=++id;pending.set(i,{r,j});ws.send(JSON.stringify({id:i,method:m,params:p}))});
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.j(m.error):p.r(m.result)}else if(m.method==='Runtime.exceptionThrown'){errors.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text)}};
 await new Promise(r=>ws.onopen=r); await send('Runtime.enable');
 await send('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:1,mobile:false,screenWidth:1440,screenHeight:900});
 await send('Page.reload',{ignoreCache:true});
 await new Promise(r=>setTimeout(r,1800));
 errors.length=0;
 let r=await send('Runtime.evaluate',{expression:`({tick:__vivarium.sim.tick,seed:__vivarium.sim.seed,docH:document.documentElement.scrollHeight,resources:performance.getEntriesByType('resource').map(x=>x.name),console:[document.querySelector('.console-scroll').clientHeight,document.querySelector('.console-scroll').scrollHeight]})`,returnByValue:true});
 console.log('intro',r.result.value);
 let shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final2-stage.png',Buffer.from(shot.data,'base64'));
 // finish
