from pathlib import Path
p=Path('index.html'); s=p.read_text()
s=s.replace("        const targets = [1, 2, 4, 5, 10, 15, 20, 25, 30, 40, 50, 60, 80, 100];", "        const targets = [1, 2, 3, 5, 6, 10, 15, 20, 25, 30, 40, 50, 60, 80, 100];")
# ARIA linked descriptions for wrappers that are themselves focusable
s=s.replace("""        document.querySelectorAll('[data-tip]').forEach(wrapper => {
          wrapper.querySelectorAll('button, input, [role="slider"]').forEach(control => {
            if (control === el.toolTip) return;
            const existing = control.getAttribute('aria-describedby');
            const ids = existing ? existing.split(/\\s+/) : [];
            if (!ids.includes('toolTip')) {
              ids.push('toolTip');
              control.setAttribute('aria-describedby', ids.filter(Boolean).join(' '));
            }
          });
        });""","""        document.querySelectorAll('[data-tip]').forEach(wrapper => {
          const candidates = [wrapper, ...wrapper.querySelectorAll('button, input, [role="slider"]')];
          candidates.filter(control => control.matches('button, input, [role="slider"]')).forEach(control => {
            if (control === el.toolTip) return;
            const existing = control.getAttribute('aria-describedby');
            const ids = existing ? existing.split(/\\s+/) : [];
            if (!ids.includes('toolTip')) {
              ids.push('toolTip');
              control.setAttribute('aria-describedby', ids.filter(Boolean).join(' '));
            }
          });
        });""")
# aria shortcuts
s=s.replace('id="playButton" type="button" aria-label="Pause the succession"', 'id="playButton" type="button" aria-label="Pause the succession" aria-keyshortcuts="Space"')
s=s.replace('id="stepButton" type="button" aria-label="Advance one simulation cycle"', 'id="stepButton" type="button" aria-label="Advance one simulation cycle" aria-keyshortcuts="."')
s=s.replace('id="restartButton" type="button" aria-label="Restart the succession with the current seed"', 'id="restartButton" type="button" aria-label="Restart the succession with the current seed" aria-keyshortcuts="R"')
p.write_text(s)
