const fs=require('fs');
(async()=>{
 const targets=await (await fetch('http://127.0.0.1/json')).json();
 const page=targets.find(t=>t.type==='page' && t.url.startsWith('file:'));
 const ws=new WebSocket(page.webSocketDebuggerUrl);
 let id=0;const pending=new Map();const errors=[];
 const send=(m,p={})=>new Promise((r,j)=>{const i=++id;pending.set(i,{r,j});ws.send(JSON.stringify({id:i,method:m,params:p}))});
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.j(m.error):p.r(m.result)}else if(m.method==='Runtime.exceptionThrown'){errors.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text)}};
 await new Promise(r=>ws.onopen=r); await send('Runtime.enable');
 await send('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:1,mobile:false,screenWidth:1440,screenHeight:900});
 await send('Page.reload',{ignoreCache:true});
 await new Promise(r=>setTimeout(r,1400));
 errors.length=0;
 // Focus a control to expose the keyboard tooltip
 await send('Runtime.evaluate',{expression:`document.getElementById('mutationRange').focus(); true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,400));
 let r=await send('Runtime.evaluate',{expression:`({tooltip:document.getElementById('toolTip').className,text:document.getElementById('toolTip').textContent.slice(0,40),ariaDesc:document.getElementById('mutationRange').getAttribute('aria-describedby'), playAria:document.getElementById('playButton').getAttribute('aria-describedby')})`,returnByValue:true});
 console.log('tooltip',r.result.value);
 // Step manually to first frost event
 r=await send('Runtime.evaluate',{expression:`(()=>{__vivarium.state.running=false; while(__vivarium.sim.tick < 11*180) __vivarium.sim.step(); return {tick:__vivarium.sim.tick, gen:__vivarium.sim.generation, events:__vivarium.sim.catastrophes.map(e=>e.key+'@'+e.generation), markerCount:document.querySelectorAll('.run-event').length, banner:document.getElementById('eventBanner').className, condition:document.getElementById('conditionText').textContent};})()`,returnByValue:true});
 console.log('event',r.result.value);
 await new Promise(r=>setTimeout(r,300));
 let shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final3-event.png',Buffer.from(shot.data,'base64'));
 // finish + report + keyboard escape
 await send('Runtime.evaluate',{expression:`__vivarium.finish(); true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,1600));
 r=await send('Runtime.evaluate',{expression:`({open:__vivarium.state.reportOpen,focus:document.activeElement.id,focusText:document.activeElement.textContent.trim().slice(0,25)})`,returnByValue:true});
 console.log('report open',r.result.value);
 // Focus last report button and Tab to test trap
 await send('Runtime.evaluate',{expression:`(()=>{const f=[...document.querySelectorAll('#report button:not([disabled])')].filter(e=>e.offsetParent!==null); f[f.length-1].focus(); return {first:f[0].id,last:f[f.length-1].id,active:document.activeElement.id};})()`,returnByValue:true});
 r=await send('Runtime.evaluate',{expression:`document.dispatchEvent(new KeyboardEvent('keydown',{key:'Tab',bubbles:true})); ({active:document.activeElement.id, insideReport:document.getElementById('report').contains(document.activeElement)})`,returnByValue:true});
 console.log('focus trap ->',r.result.value);
 // shift-tab from first
 r=await send('Runtime.evaluate',{expression:`(()=>{const f=[...document.querySelectorAll('#report button:not([disabled])')].filter(e=>e.offsetParent!==null); f[0].focus(); document.dispatchEvent(new KeyboardEvent('keydown',{key:'Tab',shiftKey:true,bubbles:true})); return {active:document.activeElement.id};})()`,returnByValue:true});
 console.log('focus trap shift ->',r.result.value);
 // Escape close
 r=await send('Runtime.evaluate',{expression:`document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true})); ({open:__vivarium.state.reportOpen, focus:document.activeElement.id, reopenHidden:document.getElementById('openReportButton').hidden})`,returnByValue:true});
 console.log('escape close ->',r.result.value);
 // mobile report
 await send('Runtime.evaluate',{expression:`document.getElementById('openReportButton').click(); true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,600));
 await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:2,mobile:true,screenWidth:390,screenHeight:844});
 await new Promise(r=>setTimeout(r,350));
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final3-mobile-report.png',Buffer.from(shot.data,'base64'));
 await send('Runtime.evaluate',{expression:`document.getElementById('report').scrollTop=1450; true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,250));
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final3-mobile-traits.png',Buffer.from(shot.data,'base64'));
 r=await send('Runtime.evaluate',{expression:`({reportW:document.getElementById('report').scrollWidth, reportClientW:document.getElementById('report').clientWidth, chartTipVisible:document.getElementById('chartTip').className, buttons:[...document.querySelectorAll('.report-actions .paper-button')].map(b=>({label:b.getAttribute('aria-label'),text:b.textContent.trim()}))})`,returnByValue:true});
 console.log('mobile report',r.result.value);
 console.log('errors',errors);
 ws.close();
})();
