 await send('Page.reload',{ignoreCache:true});
 await new Promise(r=>setTimeout(r,1200));
 // Use the actual controls to set max tempo, then let it run itself.
 let r=await send('Runtime.evaluate',{expression:`(()=>{const d=document.getElementById('tempoDial'); d.focus(); d.dispatchEvent(new KeyboardEvent('keydown',{key:'End',bubbles:true})); return {tempo:__vivarium.state.tempo, running:__vivarium.state.running,tick:__vivarium.sim.tick,gen:__vivarium.sim.generation};})()`,returnByValue:true});
