 if(!r.result.value.reportOpen){await new Promise(r=>setTimeout(r,10000)); r=await send('Runtime.evaluate',{expression:`({reportOpen:__vivarium.state.reportOpen,finished:__vivarium.sim.finished,gen:__vivarium.sim.generation,prey:__vivarium.sim.prey.length,pred:__vivarium.sim.predators.length})`,returnByValue:true}); console.log('after extra',r.result.value);}
