 console.log('after repeat',r.result.value);
 // Pause and use seed stepper
 await send('Runtime.evaluate',{expression:`document.getElementById('playButton').click(); document.getElementById('seedUp').click(); true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,300));
 r=await send('Runtime.evaluate',{expression:`({seed:__vivarium.state.seed,field:document.getElementById('seedInput').value,running:__vivarium.state.running,gen:__vivarium.sim.generation,status:document.getElementById('statusText').textContent})`,returnByValue:true});
