{"command":"node - <<'NODE'
const fs=require('fs');
(async()=>{
 const targets=await (await fetch('http://127.0.0.1/json')).json();
 const page=targets.find(t=>t.type==='page' && t.url.startsWith('file:'));
 const ws=new WebSocket(page.webSocketDebuggerUrl);
 let id=0;const pending=new Map();const errors=[];
 const send=(m,p={})=>new Promise((r,j)=>{const i=++id;pending.set(i,{r,j});ws.send(JSON.stringify({id:i,method:m,params:p}))});
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.j(m.error):p.r(m.result)}else if(m.method==='Runtime.exceptionThrown'){errors.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text)}};
 await new Promise(r=>ws.onopen=r);await send('Runtime.enable');
 for(const [w,h,name,scale] of [[1024,768,'tablet',1],[320,720,'small',2]]){
   await send('Emulation.setDeviceMetricsOverride',{width:w,height:h,deviceScaleFactor:scale,mobile:w<500,screenWidth:w,screenHeight:h});
   await send('Page.reload',{ignoreCache:true});
   await new Promise(r=>setTimeout(r,1400));
   let r=await send('Runtime.evaluate',{expression:`({w:innerWidth,h:innerHeight,docW:document.documentElement.scrollWidth,docH:document.documentElement.scrollHeight,stageW:document.getElementById('chamber').clientWidth,stageH:document.getElementById('chamber').clientHeight,runhead:document.querySelector('.runhead').getBoundingClientRect().width,seed:__vivarium.sim.seed,tick:__vivarium.sim.tick})`,returnByValue:true});
   console.log(name,r.result.value);
   await send('Runtime.evaluate',{expression:`window.scrollTo(0,0); true`,returnByValue:true});
   let shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync(`<TMP>/final-${name}.png`,Buffer.from(shot.data,'base64'));
 }
 console.log('errors',errors);
 ws.close();
})();
