{"command":"node - <<'NODE'
(async()=>{
 const targets=await (await fetch('http://127.0.0.1/json')).json();
 const page=targets.find(t=>t.type==='page' && t.url.startsWith('file:'));
 const ws=new WebSocket(page.webSocketDebuggerUrl);let id=0;const pending=new Map();
 const send=(m,p={})=>new Promise((r,j)=>{const i=++id;pending.set(i,{r,j});ws.send(JSON.stringify({id:i,method:m,params:p}))});
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.j(m.error):p.r(m.result)}};
 await new Promise(r=>ws.onopen=r);await send('Runtime.enable');
 for(const w of [700,800,900]){
  await send('Emulation.setDeviceMetricsOverride',{width:w,height:900,deviceScaleFactor:1,mobile:false,screenWidth:w,screenHeight:900}); await send('Page.reload',{ignoreCache:true}); await new Promise(r=>setTimeout(r,800));
  const r=await send('Runtime.evaluate',{expression:`(()=>{const a=document.querySelector('.identity').getBoundingClientRect(),b=document.querySelector('.runhead').getBoundingClientRect(),t=document.querySelector('.title-main').getBoundingClientRect();return {w:innerWidth,docW:document.documentElement.scrollWidth,identity:[a.left,a.right,a.width],title:[t.left,t.right,t.width],runhead:[b.left,b.right,b.width],overlap:a.right>b.left, mast:getComputedStyle(document.querySelector('.masthead')).gridTemplateColumns}})()`,returnByValue:true});
  console.log(w,r.result.value);
 }
 ws.close();
})();
NODE","description":"Measure header overlap at mid widths"}

