{"command":"node - <<'NODE'
const fs=require('fs');
(async()=>{
 const targets=await (await fetch('http://127.0.0.1/json')).json();
 const page=targets.find(t=>t.type==='page' && t.url.startsWith('file:'));
 const ws=new WebSocket(page.webSocketDebuggerUrl);
 let id=0;const pending=new Map();const errors=[];
 const send=(m,p={})=>new Promise((r,j)=>{const i=++id;pending.set(i,{r,j});ws.send(JSON.stringify({id:i,method:m,params:p}))});
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.j(m.error):p.r(m.result)}else if(m.method==='Runtime.exceptionThrown'){errors.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text)}};
 await new Promise(r=>ws.onopen=r);await send('Runtime.enable');
 // 1024 layout
 await send('Emulation.setDeviceMetricsOverride',{width:1024,height:768,deviceScaleFactor:1,mobile:false,screenWidth:1024,screenHeight:768});
 await send('Page.reload',{ignoreCache:true}); await new Promise(r=>setTimeout(r,1200));
 let r=await send('Runtime.evaluate',{expression:`(()=>{const t=document.querySelector('.title-main').getBoundingClientRect(),rh=document.querySelector('.runhead').getBoundingClientRect(),deck=document.querySelector('.deck').getBoundingClientRect();return {docW:document.documentElement.scrollWidth,titleRight:Math.round(t.right),runheadLeft:Math.round(rh.left),deckTop:Math.round(deck.top),overlap:t.right>rh.left,resources:performance.getEntriesByType('resource').map(x=>x.name)}})()`,returnByValue:true});
 console.log('1024',r.result.value);
 let shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final5-tablet.png',Buffer.from(shot.data,'base64'));
 // 320 key fit
 await send('Emulation.setDeviceMetricsOverride',{width:320,height:720,deviceScaleFactor:2,mobile:true,screenWidth:320,screenHeight:720});
 await send('Page.reload',{ignoreCache:true}); await new Promise(r=>setTimeout(r,1000));
 r=await send('Runtime.evaluate',{expression:`(()=>{const k=document.querySelector('.species-key').getBoundingClientRect();const items=[...document.querySelectorAll('.key-item')].map(e=>{const r=e.getBoundingClientRect();return [Math.round(r.left),Math.round(r.right)]});return {docW:document.documentElement.scrollWidth, key:[Math.round(k.left),Math.round(k.right)], items, keyScroll:[document.querySelector('.species-key').clientWidth,document.querySelector('.species-key').scrollWidth]}})()`,returnByValue:true});
 console.log('320',r.result.value);
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final5-small.png',Buffer.from(shot.data,'base64'));
 // 390 report ledger
 await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:2,mobile:true,screenWidth:390,screenHeight:844});
 await send('Page.reload',{ignoreCache:true}); await new Promise(r=>setTimeout(r,1000));
 await send('Runtime.evaluate',{expression:`__vivarium.finish(); true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,1600));
 r=await send('Runtime.evaluate',{expression:`(()=>{const list=document.querySelector('.event-ledger-list');return {open:__vivarium.state.reportOpen, reportW:document.getElementById('report').scrollWidth, listClient:list.clientHeight, listScroll:list.scrollHeight, eventRows:list.children.length, activeFocus:document.activeElement.id};})()`,returnByValue:true});
 console.log('390 report',r.result.value);
 await send('Runtime.evaluate',{expression:`document.getElementById('report').scrollTop = document.querySelector('.ledger').offsetTop - 220; true`,returnByValue:true});
 await new Promise(r=>setTimeout(r,250));
 shot=await send('Page.captureScreenshot',{format:'png'});fs.writeFileSync('<TMP>/final5-mobile-ledger.png',Buffer.from(shot.data,'base64'));
 console.log('errors',errors);
 ws.close();
})();
